// Native PC build: self-tests that need the real game code linked in.
//
//   pokeemerald-mp --selftest-decompress LIST
//
// LIST has one "COMPRESSED EXPECTED" pair of file paths per line (generated by
// tools/pc_port/make_decompress_list.py from build/assets). Each compressed
// asset is decoded with the game's own decompressor, natively, through both the
// WRAM and VRAM entry points, and compared byte for byte with the uncompressed
// file the GBA build compressed it from. A guard area after the output buffer
// catches overruns. Runs before the game starts and exits with the result.
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "global.h"
#include "decompress.h"
#include "malloc.h"

#define GUARD_SIZE 256
#define GUARD_BYTE 0xA5

static u8 *ReadWholeFile(const char *path, size_t *size)
{
    FILE *file = fopen(path, "rb");
    u8 *data;
    long length;

    if (file == NULL)
        return NULL;
    fseek(file, 0, SEEK_END);
    length = ftell(file);
    fseek(file, 0, SEEK_SET);
    // Over-allocate and zero: decoders read whole 32-bit words past the end.
    data = calloc(1, (size_t)length + 16);
    if (data != NULL && fread(data, 1, (size_t)length, file) != (size_t)length)
    {
        free(data);
        data = NULL;
    }
    fclose(file);
    *size = (size_t)length;
    return data;
}

static int FirstDifference(const u8 *a, const u8 *b, size_t size)
{
    for (size_t i = 0; i < size; i++)
    {
        if (a[i] != b[i])
            return (int)i;
    }
    return -1;
}

static bool32 GuardIntact(const u8 *guard)
{
    for (int i = 0; i < GUARD_SIZE; i++)
    {
        if (guard[i] != GUARD_BYTE)
            return FALSE;
    }
    return TRUE;
}

// Returns 0 when every asset decodes to its reference.
int NativeSelfTest_Decompress(const char *listPath)
{
    FILE *list = fopen(listPath, "r");
    char compressedPath[1024], expectedPath[1024];
    int tested = 0, failed = 0, skipped = 0;

    if (list == NULL)
    {
        fprintf(stderr, "selftest: cannot open %s\n", listPath);
        return 2;
    }
    InitHeap(gHeap, HEAP_SIZE); // the smol decoder allocates its work buffers from the game heap

    while (fscanf(list, "%1023s %1023s", compressedPath, expectedPath) == 2)
    {
        size_t compressedSize, expectedSize;
        u8 *compressed = ReadWholeFile(compressedPath, &compressedSize);
        u8 *expected = ReadWholeFile(expectedPath, &expectedSize);
        u32 declaredSize;

        if (compressed == NULL || expected == NULL || compressedSize < 8)
        {
            printf("SKIP %s (unreadable)\n", compressedPath);
            skipped++;
            free(compressed);
            free(expected);
            continue;
        }
        declaredSize = GetDecompressedDataSize((const u32 *)compressed);
        tested++;
        if (declaredSize != expectedSize)
        {
            printf("FAIL %s: header size %u, reference %u bytes\n", compressedPath,
                   (unsigned)declaredSize, (unsigned)expectedSize);
            failed++;
        }
        else
        {
            for (int vram = 0; vram < 2; vram++)
            {
                u8 *output = malloc(expectedSize + GUARD_SIZE);
                int diff;

                memset(output, 0, expectedSize);
                memset(output + expectedSize, GUARD_BYTE, GUARD_SIZE);
                if (vram)
                    DecompressDataWithHeaderVram((const u32 *)compressed, output);
                else
                    DecompressDataWithHeaderWram((const u32 *)compressed, output);
                diff = FirstDifference(output, expected, expectedSize);
                if (diff >= 0 || !GuardIntact(output + expectedSize))
                {
                    printf("FAIL %s (%s): ", compressedPath, vram ? "VRAM" : "WRAM");
                    if (diff >= 0)
                        printf("first difference at byte %d of %u (got %02x, want %02x)\n",
                               diff, (unsigned)expectedSize, output[diff], expected[diff]);
                    else
                        printf("wrote past the end of its output\n");
                    failed++;
                    free(output);
                    break;
                }
                free(output);
            }
        }
        free(compressed);
        free(expected);
    }
    fclose(list);
    printf("selftest-decompress: %d assets, %d failed, %d skipped\n", tested, failed, skipped);
    return failed ? 1 : 0;
}

// ---------------------------------------------------------------------------
//   pokeemerald-mp --selftest-party-order
//
// The battle's party order (party_menu.c): which party slot each of a side's
// six battle slots shows, two 4-bit party indexes a byte. InitBattleControllers
// builds it for every battler of a battle that is not a Multi
// (BufferBattlePartyCurrentOrderBySide), and coming back from the bag or the
// party menu builds the player's again (BufferBattlePartyCurrentOrder).
//
// KNOWN_ISSUES N37: against two opponent trainers each trainer has a party of
// its own (gParties[B_TRAINER_OPPONENT_A] and _B), so both opponents are party
// index 0 and the double-battle branch wrote a seventh index one byte past its
// six-entry array - natively "stack smashing detected" as the battle started.
// Every single, double, two-opponent and Multi layout is run here, with every
// pair of party indexes: each call must return, and give the order the game has
// always given (Reference: the six indexes the GBA keeps in bounds), so the fix
// changes no battle. Runs before the game starts and exits with the result.
#include "battle.h"
#include "battle_util.h"
#include "main.h"
#include "party_menu.h"
#include "constants/battle.h"

static int sOrderChecks, sOrderFailures;

// The order as the game computes it, in a buffer with room for the seventh
// index the double-battle branch can write; the game keeps the first six.
static void ReferenceOrder(u8 out[PARTY_SIZE / 2], u32 typeFlags, u8 left, u8 right, u8 flankId,
                           bool32 fullTeams)
{
    u8 ids[PARTY_SIZE + 1];
    int i, j;

    if ((typeFlags & BATTLE_TYPE_MULTI) && (typeFlags & BATTLE_TYPE_MORE_THAN_TWO_BATTLERS))
    {
        static const u8 sFull[3] = {(0 << 4) | 1, (2 << 4) | 3, (4 << 4) | 5};
        static const u8 sRight[3] = {0 | (3 << 4), 5 | (4 << 4), 2 | (1 << 4)};
        static const u8 sLeft[3] = {3 | (0 << 4), 2 | (1 << 4), 5 | (4 << 4)};

        memcpy(out, fullTeams ? sFull : (flankId != 0 ? sRight : sLeft), 3);
        return;
    }
    if (!(typeFlags & BATTLE_TYPE_MORE_THAN_TWO_BATTLERS))
    {
        j = 1;
        ids[0] = left;
        for (i = 0; i < PARTY_SIZE; i++)
            if (i != ids[0])
                ids[j++] = i;
    }
    else
    {
        j = 2;
        ids[0] = left;
        ids[1] = right;
        for (i = 0; i < PARTY_SIZE && j <= PARTY_SIZE; i++)
            if (i != ids[0] && i != ids[1])
                ids[j++] = i;
    }
    for (i = 0; i < 3; i++)
        out[i] = (ids[i * 2] << 4) | ids[i * 2 + 1];
}

static void SetOrderBattle(u32 typeFlags)
{
    gBattleTypeFlags = typeFlags;
    gBattlersCount = (typeFlags & BATTLE_TYPE_MORE_THAN_TWO_BATTLERS) ? MAX_BATTLERS_COUNT : 2;
    gBattlerPositions[0] = B_POSITION_PLAYER_LEFT;
    gBattlerPositions[1] = B_POSITION_OPPONENT_LEFT;
    gBattlerPositions[2] = B_POSITION_PLAYER_RIGHT;
    gBattlerPositions[3] = B_POSITION_OPPONENT_RIGHT;
    gMain.inBattle = TRUE;
}

static void ExpectOrder(const char *what, const u8 *got, const u8 *want)
{
    sOrderChecks++;
    if (memcmp(got, want, PARTY_SIZE / 2) == 0)
        return;
    sOrderFailures++;
    printf("FAIL %s: order %02x %02x %02x, want %02x %02x %02x\n", what,
           got[0], got[1], got[2], want[0], want[1], want[2]);
}

// One battler's side, as InitBattleControllers builds it.
static void CheckSideOrder(const char *layout, u32 typeFlags, enum BattlerId battler, u8 flankId)
{
    enum BattlerId left = (battler & BIT_SIDE) ? 1 : 0;
    u8 want[PARTY_SIZE / 2];
    u8 *got = gBattleStruct->battlerPartyOrders[battler];
    bool32 fullTeams = FALSE;
    char what[160];

    if ((typeFlags & BATTLE_TYPE_MULTI) && (typeFlags & BATTLE_TYPE_MORE_THAN_TWO_BATTLERS))
        fullTeams = AreMultiPartiesFullTeams();
    ReferenceOrder(want, typeFlags, gBattlerPartyIndexes[left], gBattlerPartyIndexes[left + 2], flankId,
                   fullTeams);
    snprintf(what, sizeof(what), "%s, battler %d (party indexes %d and %d), flank %d", layout, battler,
             gBattlerPartyIndexes[left], gBattlerPartyIndexes[left + 2], flankId);
    // a crash here is the bug itself: name the case first
    printf("  %s\n", what);
    fflush(stdout);
    memset(got, 0xEE, PARTY_SIZE / 2);
    BufferBattlePartyCurrentOrderBySide(battler, flankId);
    ExpectOrder(what, got, want);
}

// The player's side, as coming back from the bag or the party menu builds it.
static void CheckPlayerOrder(const char *layout, u32 typeFlags)
{
    u8 want[PARTY_SIZE / 2];
    char what[160];

    ReferenceOrder(want, typeFlags, gBattlerPartyIndexes[0], gBattlerPartyIndexes[2], GetPlayerFlankId(),
                   (typeFlags & BATTLE_TYPE_MULTI) && (typeFlags & BATTLE_TYPE_MORE_THAN_TWO_BATTLERS)
                   ? AreMultiPartiesFullTeams() : FALSE);
    snprintf(what, sizeof(what), "%s, the player's order (party indexes %d and %d)", layout,
             gBattlerPartyIndexes[0], gBattlerPartyIndexes[2]);
    printf("  %s\n", what);
    fflush(stdout);
    memset(gBattlePartyCurrentOrder, 0xEE, sizeof(gBattlePartyCurrentOrder));
    BufferBattlePartyCurrentOrder();
    ExpectOrder(what, gBattlePartyCurrentOrder, want);
}

int NativeSelfTest_PartyOrder(void)
{
    static const struct { const char *name; u32 flags; } sLayouts[] =
    {
        {"single, wild", 0},
        {"single, trainer", BATTLE_TYPE_TRAINER},
        {"double, wild", BATTLE_TYPE_DOUBLE},
        {"double, one trainer", BATTLE_TYPE_TRAINER | BATTLE_TYPE_DOUBLE},
        {"double, two opponent trainers", BATTLE_TYPE_TRAINER | BATTLE_TYPE_DOUBLE | BATTLE_TYPE_TWO_OPPONENTS},
        {"multi, in-game partner, wild", BATTLE_TYPE_DOUBLE | BATTLE_TYPE_MULTI | BATTLE_TYPE_INGAME_PARTNER},
        {"multi, in-game partner, two trainers", BATTLE_TYPE_TRAINER | BATTLE_TYPE_DOUBLE | BATTLE_TYPE_TWO_OPPONENTS
                                                 | BATTLE_TYPE_MULTI | BATTLE_TYPE_INGAME_PARTNER},
        {"multi, link (half teams)", BATTLE_TYPE_TRAINER | BATTLE_TYPE_DOUBLE | BATTLE_TYPE_MULTI
                                     | BATTLE_TYPE_TOWER_LINK_MULTI},
    };
    // The N37 battle itself, spelt out: both opponents party index 0 of their own party.
    static const u8 sTwoOpponents[PARTY_SIZE / 2] = {(0 << 4) | 0, (1 << 4) | 2, (3 << 4) | 4};
    // and the player's own two, party indexes 0 and 1
    static const u8 sPlayerFirstTwo[PARTY_SIZE / 2] = {(0 << 4) | 1, (2 << 4) | 3, (4 << 4) | 5};

    gBattleStruct = calloc(1, sizeof(*gBattleStruct));
    if (gBattleStruct == NULL)
        return 2;

    // The battle N37 was found in (Sootopolis Gym B1F, two trainers see the
    // player together), first: both opponents party index 0 of their own party.
    printf("two opponent trainers, both party index 0 (N37)\n");
    fflush(stdout);
    SetOrderBattle(BATTLE_TYPE_TRAINER | BATTLE_TYPE_DOUBLE | BATTLE_TYPE_TWO_OPPONENTS);
    gBattlerPartyIndexes[0] = 0;
    gBattlerPartyIndexes[2] = 1;
    gBattlerPartyIndexes[1] = 0;
    gBattlerPartyIndexes[3] = 0;
    for (enum BattlerId battler = 0; battler < MAX_BATTLERS_COUNT; battler++)
    {
        memset(gBattleStruct->battlerPartyOrders[battler], 0xEE, PARTY_SIZE / 2);
        BufferBattlePartyCurrentOrderBySide(battler, 0);
    }
    ExpectOrder("two opponent trainers (N37), opponent A", gBattleStruct->battlerPartyOrders[1], sTwoOpponents);
    ExpectOrder("two opponent trainers (N37), opponent B", gBattleStruct->battlerPartyOrders[3], sTwoOpponents);
    ExpectOrder("two opponent trainers (N37), the player", gBattleStruct->battlerPartyOrders[0], sPlayerFirstTwo);

    for (u32 l = 0; l < ARRAY_COUNT(sLayouts); l++)
    {
        u32 flags = sLayouts[l].flags;
        bool32 doubles = (flags & BATTLE_TYPE_MORE_THAN_TWO_BATTLERS) != 0;

        printf("%s\n", sLayouts[l].name);
        SetOrderBattle(flags);
        for (u32 a = 0; a < PARTY_SIZE; a++)
        {
            for (u32 b = 0; b < PARTY_SIZE; b++)
            {
                // left battlers a, right battlers b (in a single only the left ones fight)
                gBattlerPartyIndexes[0] = a;
                gBattlerPartyIndexes[1] = a;
                gBattlerPartyIndexes[2] = b;
                gBattlerPartyIndexes[3] = b;
                for (enum BattlerId battler = 0; battler < gBattlersCount; battler++)
                    CheckSideOrder(sLayouts[l].name, flags, battler, battler >= 2);
                CheckPlayerOrder(sLayouts[l].name, flags);
                if (!doubles)
                    break;
            }
        }
    }

    free(gBattleStruct);
    gBattleStruct = NULL;
    gMain.inBattle = FALSE;
    printf("selftest-party-order: %d checks, %d failed\n", sOrderChecks, sOrderFailures);
    return sOrderFailures ? 1 : 0;
}

// ---------------------------------------------------------------------------
//   pokeemerald-mp --selftest-battle-names
//
// A battle message naming trainers with their classes (battle_message.c,
// BattleStringExpandPlaceholders). KNOWN_ISSUES N38: the text of each
// {B_TRAINERn_NAME_WITH_CLASS} was put together in a 32-byte buffer from where the
// one before it ended, so a message naming two trainers - "You are challenged by
// MAGMA LEADER MAXIE and MAGMA ADMIN TABITHA!", Mossdeep's Space Center Multi
// battle - wrote past it: natively "stack smashing detected" as the battle began.
// Here the two-opponent intro's placeholders are expanded for every pair of
// opponents a two-trainer battle of the game has (and that pair with the longest
// names of all trainers): each must return, and give each trainer's class and
// name as the game always has (each placeholder expanded alone, which never
// overflowed, is the reference). Runs before the game starts and exits with the
// result.
#include "battle_message.h"
#include "battle_setup.h"
#include "data.h"
#include "string_util.h"
#include "constants/characters.h"
#include "constants/opponents.h"
#include "constants/trainers.h"

static int sNameChecks, sNameFailures;

// A copy of the message without its line breaks and kinds of space (the
// message box breaks lines by width), to compare words only.
static void Words(const u8 *src, u8 *dst, size_t size)
{
    size_t n = 0;

    for (; *src != EOS && n + 1 < size; src++)
        dst[n++] = (*src == CHAR_NBSP || *src == CHAR_NEWLINE || *src == CHAR_PROMPT_SCROLL
                    || *src == CHAR_PROMPT_CLEAR) ? CHAR_SPACE : *src;
    dst[n] = EOS;
}

static void Expand(const u8 *placeholders, u8 *out, size_t size)
{
    u8 dst[256];

    memset(dst, EOS, sizeof(dst));
    BattleStringExpandPlaceholders(placeholders, dst, sizeof(dst));
    Words(dst, out, size);
}

static void CheckTwoTrainerNames(u16 opponentA, u16 opponentB)
{
    static const u8 sBoth[] = {PLACEHOLDER_BEGIN, B_TXT_TRAINER1_NAME_WITH_CLASS, CHAR_SPACE,
                               PLACEHOLDER_BEGIN, B_TXT_TRAINER2_NAME_WITH_CLASS, EOS};
    static const u8 sFirst[] = {PLACEHOLDER_BEGIN, B_TXT_TRAINER1_NAME_WITH_CLASS, EOS};
    static const u8 sSecond[] = {PLACEHOLDER_BEGIN, B_TXT_TRAINER2_NAME_WITH_CLASS, EOS};
    u8 both[256], first[128], second[128], want[256];
    size_t n;

    TRAINER_BATTLE_PARAM.opponentA = opponentA;
    TRAINER_BATTLE_PARAM.opponentB = opponentB;
    printf("  trainers %d and %d\n", opponentA, opponentB);
    fflush(stdout);
    // a crash here is the bug itself: the case is named first
    Expand(sBoth, both, sizeof(both));
    Expand(sFirst, first, sizeof(first));
    Expand(sSecond, second, sizeof(second));
    n = StringLength(first);
    memcpy(want, first, n);
    want[n] = CHAR_SPACE;
    memcpy(want + n + 1, second, StringLength(second) + 1);
    sNameChecks++;
    if (StringCompare(both, want) != 0)
    {
        sNameFailures++;
        printf("FAIL trainers %d and %d: the two names differ from each alone\n", opponentA, opponentB);
    }
}

// The trainer of the game with the longest class and name together.
static u16 LongestNamedTrainer(void)
{
    u16 best = TRAINER_NONE + 1;
    u32 bestLength = 0;

    for (u16 id = TRAINER_NONE + 1; id < TRAINERS_COUNT; id++)
    {
        u32 length;

        if (id == TRAINER_FRONTIER_BRAIN)
            continue;
        length = StringLength(GetTrainerNameFromId(id))
               + StringLength(gTrainerClasses[GetTrainerClassFromId(id)].name);

        if (length > bestLength)
        {
            bestLength = length;
            best = id;
        }
    }
    return best;
}

int NativeSelfTest_BattleNames(void)
{
    // The two-trainer battles of the game (data/maps/*/scripts.inc: the Space
    // Center's multi_2_vs_2, the two-trainer intros of trainer pairs) are
    // covered by their longest case, and the Space Center's first.
    u16 longest = LongestNamedTrainer();

    InitHeap(gHeap, HEAP_SIZE); // the message box's line breaking allocates from the game heap
    gBattleTypeFlags = BATTLE_TYPE_TRAINER | BATTLE_TYPE_DOUBLE | BATTLE_TYPE_TWO_OPPONENTS
                     | BATTLE_TYPE_MULTI | BATTLE_TYPE_INGAME_PARTNER;
    printf("Mossdeep's Space Center: MAXIE and TABITHA (N38)\n");
    CheckTwoTrainerNames(TRAINER_MAXIE_MOSSDEEP, TRAINER_TABITHA_MOSSDEEP);
    printf("the longest class and name, twice\n");
    CheckTwoTrainerNames(longest, longest);
    gBattleTypeFlags = BATTLE_TYPE_TRAINER | BATTLE_TYPE_DOUBLE | BATTLE_TYPE_TWO_OPPONENTS;
    printf("every trainer against the longest\n");
    for (u16 id = TRAINER_NONE + 1; id < TRAINERS_COUNT; id++)
    {
        // the Battle Frontier's ids share their numbers with the game's trainers, and
        // this one is read as the Frontier Brain (its class from the Frontier's save
        // data, which a selftest does not have)
        if (id == TRAINER_FRONTIER_BRAIN)
            continue;
        CheckTwoTrainerNames(longest, id);
        CheckTwoTrainerNames(id, longest);
    }
    gBattleTypeFlags = 0;
    printf("selftest-battle-names: %d checks, %d failed\n", sNameChecks, sNameFailures);
    return sNameFailures ? 1 : 0;
}

// ---------------------------------------------------------------------------
//   pokeemerald-mp --selftest-cry-stop
//
// The Pokemon cry functions before any cry has played since the game started
// (sound.c: gMPlay_PokemonCry stays NULL until the first one). KNOWN_ISSUES N39:
// as a double battle sends its first two Pokemon out
// (Task_PlayCryWhenReleasedFromBall) it stops the cry playing before the doubles'
// cries (StopCryAndClearCrySongs), and with none played yet m4aMPlayStop read
// through that NULL - natively a segmentation fault as a two-trainer battle began
// right after a save was continued; the GBA reads its BIOS there and does nothing.
// Each function must return with no cry playing and no cry player set.
// ---------------------------------------------------------------------------

#include "sound.h"

extern struct MusicPlayerInfo *gMPlay_PokemonCry;

static int sCryChecks, sCryFailures;

static void ExpectCry(const char *what, bool32 ok)
{
    sCryChecks++;
    if (!ok)
    {
        sCryFailures++;
        printf("FAIL %s\n", what);
    }
}

int NativeSelfTest_CryStop(void)
{
    gMPlay_PokemonCry = NULL;
    printf("a double battle's send-out stopping the cry before any cry has played\n");
    fflush(stdout);
    StopCryAndClearCrySongs();
    ExpectCry("StopCryAndClearCrySongs returned", TRUE);
    StopCry();
    ExpectCry("StopCry returned", TRUE);
    ExpectCry("IsCryPlaying: none", !IsCryPlaying());
    ExpectCry("IsCryPlayingOrClearCrySongs: none", !IsCryPlayingOrClearCrySongs());
    ExpectCry("still no cry player", gMPlay_PokemonCry == NULL);
    printf("selftest-cry-stop: %d checks, %d failed\n", sCryChecks, sCryFailures);
    return sCryFailures ? 1 : 0;
}

// ---------------------------------------------------------------------------
//   pokeemerald-mp --selftest-shake-anim
//
// A move animation shaking a battler or the battle's background
// (battle_anim_normal.c, AnimShakeMonOrBattlePlatforms: Rock Throw, Rock Slide,
// Metal Claw, Dragon Claw, Ancient Power, Superpower, Snore, Avalanche...). It keeps
// the address of what it shakes (gBattle_BG3_X or _Y, gSpriteCoordOffsetX or _Y) in
// two s16 fields and puts it back together as lo | hi << 16. KNOWN_ISSUES N40: on
// the GBA those variables are in IWRAM, whose addresses never have bit 15 set;
// natively they can, the s16 low half is then negative and sign-extends over the
// high half, and the animation reads and writes through 0xFFFFxxxx - a segmentation
// fault in the move's animation (the 3D build's layout has all four so; Mossdeep's
// Space Center Multi battle crashed so). Here the animation shakes each of the four,
// and once more a value at an address with bit 15 set in any layout (the address
// put in the sprite's fields after the animation began, as it keeps it); each must
// shake and come back to its value.
// ---------------------------------------------------------------------------

#include "battle_anim.h"
#include "sprite.h"
#include "constants/battle_anim.h"

extern const struct SpriteTemplate gShakeMonOrPlatformSpriteTemplate;

static int sShakeChecks, sShakeFailures;
// u16s across 64 KiB and a little more (allocated by the selftest only): some of them have
// addresses with bit 15 set
#define SHAKE_SPACE (0x8000 + 16)

static void ExpectShake(const char *what, bool32 ok)
{
    sShakeChecks++;
    if (!ok)
    {
        sShakeFailures++;
        printf("FAIL %s\n", what);
    }
}

// Starts the animation on target type `type` (the game's createsprite call), then
// optionally points its fields at `inject`; runs it to its end. Returns whether the
// value shook (changed while it ran).
static bool32 RunShake(u8 type, u16 *watched, u16 *inject)
{
    bool32 shook = FALSE;
    u16 start = *watched;
    u8 spriteId;
    int steps;

    gBattleAnimArgs[0] = 2;    // velocity
    gBattleAnimArgs[1] = 1;    // shake timer
    gBattleAnimArgs[2] = 8;    // shake duration
    gBattleAnimArgs[3] = type;
    gBattleAnimArgs[4] = 0;    // battler selector: the attacker
    spriteId = CreateSpriteAndAnimate(&gShakeMonOrPlatformSpriteTemplate, 0, 0, 0);
    if (spriteId == MAX_SPRITES)
        return FALSE;
    if (inject != NULL)
    {
        gSprites[spriteId].data[4] = *inject;                  // the value to come back to
        gSprites[spriteId].data[6] = (u32)inject & 0xFFFF;     // as StoreSpriteCallbackInData6
        gSprites[spriteId].data[7] = (u32)inject >> 16;
    }
    for (steps = 0; steps < 64 && gSprites[spriteId].inUse; steps++)
    {
        gSprites[spriteId].callback(&gSprites[spriteId]);
        if (*watched != start)
            shook = TRUE;
    }
    return shook && !gSprites[spriteId].inUse;
}

int NativeSelfTest_ShakeAnim(void)
{
    static const char *const names[4] = {"gBattle_BG3_X", "gBattle_BG3_Y", "gSpriteCoordOffsetX",
                                         "gSpriteCoordOffsetY"};
    u16 *targets[4] = {&gBattle_BG3_X, &gBattle_BG3_Y, (u16 *)&gSpriteCoordOffsetX,
                       (u16 *)&gSpriteCoordOffsetY};
    u16 *space = calloc(SHAKE_SPACE, sizeof(u16));
    u16 *high = NULL;
    char what[96];
    u32 i;
    u8 type;

    ResetSpriteData();
    gBattlersCount = 2;
    for (type = SHAKE_BG_X; type <= SHAKE_MON_Y; type++)
    {
        printf("shaking %s at %p (address bit 15 %s)\n", names[type], (void *)targets[type],
               ((u32)targets[type] & 0x8000) ? "set: sign-extends" : "clear");
        fflush(stdout);
        *targets[type] = 100;
        snprintf(what, sizeof(what), "%s shook and the animation ended", names[type]);
        ExpectShake(what, RunShake(type, targets[type], NULL));
        snprintf(what, sizeof(what), "%s back to its value", names[type]);
        ExpectShake(what, *targets[type] == 100);
    }
    for (i = 0; space != NULL && i < SHAKE_SPACE; i++)
        if (((u32)&space[i] & 0x8000) != 0)
        {
            high = &space[i];
            break;
        }
    if (high == NULL)
    {
        printf("FAIL no memory for the test\n");
        return 1;
    }
    printf("shaking a value at %p (address bit 15 set)\n", (void *)high);
    fflush(stdout);
    *high = 200;
    gBattle_BG3_Y = 100;
    ExpectShake("a value at an address with bit 15 set shook", RunShake(SHAKE_BG_Y, high, high));
    ExpectShake("... back to its value", *high == 200);
    ExpectShake("... and the background's value left alone", gBattle_BG3_Y == 100);
    free(space);
    ResetSpriteData();
    printf("selftest-shake-anim: %d checks, %d failed\n", sShakeChecks, sShakeFailures);
    return sShakeFailures ? 1 : 0;
}

// ---------------------------------------------------------------------------
//   pokeemerald-mp --selftest-line-break
//
// KNOWN_ISSUES U13: BattleStringExpandPlaceholders turns every space of a
// trainer's defeat line into a no-break space, so a sentence a little wider
// than the battle message box became one word; BreakSubStringAutomatic's first
// count then allocated a line its layout left empty, and BuildNewString wrote a
// line break over the end mark and read that line through an unset pointer:
// natively a fault right after Psychic Edward's battle on Route 110. The eight
// texts the native UI session's scan found (every trainerbattle text in data/
// and the secret base texts; U13-ROUTE110-CRASH.txt), copied here from data/,
// as trainer A's and trainer B's defeat line through the real
// BattleStringExpandPlaceholders, and one line that fits as a control. Each must
// come back whole: the same words, the pause code, then the end mark.
// ---------------------------------------------------------------------------

#include "line_break.h"

extern const u8 SecretBase_Text_Trainer4Defeated[];

static int sBreakChecks, sBreakFailures;

static void ExpectBreak(const char *what, bool32 ok)
{
    sBreakChecks++;
    if (!ok)
    {
        sBreakFailures++;
        printf("FAIL %s\n", what);
    }
}

static void CheckLoseText(const char *label, const u8 *text, bool32 trainerB)
{
    static const u8 sLoseA[] = {PLACEHOLDER_BEGIN, B_TXT_TRAINER1_LOSE_TEXT, EOS};
    static const u8 sLoseB[] = {PLACEHOLDER_BEGIN, B_TXT_TRAINER2_LOSE_TEXT, EOS};
    u8 dst[300], got[300], want[300];
    char what[160];
    u32 end, n;

    if (trainerB)
        TRAINER_BATTLE_PARAM.defeatTextB = (u8 *)text;
    else
        TRAINER_BATTLE_PARAM.defeatTextA = (u8 *)text;
    printf("  %s, trainer %c\n", label, trainerB ? 'B' : 'A');
    fflush(stdout); // a crash here is the bug itself: the case is named first
    memset(dst, 0xEE, sizeof(dst)); // no end mark anywhere but where the game writes one
    BattleStringExpandPlaceholders(trainerB ? sLoseB : sLoseA, dst, sizeof(dst));
    for (end = 0; end < sizeof(dst) && dst[end] != EOS; end++)
        ;
    snprintf(what, sizeof(what), "%s (trainer %c): an end mark", label, trainerB ? 'B' : 'A');
    ExpectBreak(what, end < sizeof(dst));
    if (end >= sizeof(dst))
        return;
    snprintf(what, sizeof(what), "%s (trainer %c): the pause code right before the end mark", label,
             trainerB ? 'B' : 'A');
    ExpectBreak(what, end >= 2 && dst[end - 2] == EXT_CTRL_CODE_BEGIN && dst[end - 1] == EXT_CTRL_CODE_PAUSE_UNTIL_PRESS);
    // The same words as the text (line breaks and kinds of space aside).
    Words(dst, got, sizeof(got));
    Words(text, want, sizeof(want));
    n = StringLength(want);
    want[n] = EXT_CTRL_CODE_BEGIN;
    want[n + 1] = EXT_CTRL_CODE_PAUSE_UNTIL_PRESS;
    want[n + 2] = EOS;
    snprintf(what, sizeof(what), "%s (trainer %c): every word, nothing after it", label, trainerB ? 'B' : 'A');
    ExpectBreak(what, StringCompare(got, want) == 0);
}

int NativeSelfTest_LineBreak(void)
{
    static const struct { const char *label; const u8 *text; } sTexts[] = {
        {"Route110_Text_EdwardDefeated", COMPOUND_STRING("I failed to prophesize my own demise!")},
        {"MossdeepCity_Gym_Text_MauraDefeat", COMPOUND_STRING("You've traveled a path of greatness!")},
        {"MtChimney_Text_MelissaDefeat", COMPOUND_STRING("Ooh, that was a scorching-hot match!")},
        {"Route123_Text_AlbertoDefeat", COMPOUND_STRING("Even in defeat, BIRD POKéMON are cool!")},
        {"Route124_Text_LilaRematchDefeat", COMPOUND_STRING("LILA: ROY!\nIt's your fault we lost again!\p"
                                                            "We're having a training session later!")},
        {"Route130_Text_SantiagoDefeat", COMPOUND_STRING("I needed to be a little less peaceful!")},
        {"VictoryRoad_B1F_Text_MitchellDefeat", COMPOUND_STRING("I've never met anyone like you before.")},
        {"SecretBase_Text_Trainer4Defeated", SecretBase_Text_Trainer4Defeated},
        {"a line that fits (control)", COMPOUND_STRING("Oops! I ended up losing!")},
    };
    u32 i;

    InitHeap(gHeap, HEAP_SIZE); // the message box's line breaking allocates from the game heap
    gBattleTypeFlags = BATTLE_TYPE_TRAINER;
    TRAINER_BATTLE_PARAM.opponentA = TRAINER_EDWARD; // not the secret base trainer: its text is read as given
    TRAINER_BATTLE_PARAM.opponentB = TRAINER_EDWARD;
    printf("trainer defeat lines a little wider than the message box (U13)\n");
    for (i = 0; i < ARRAY_COUNT(sTexts); i++)
    {
        CheckLoseText(sTexts[i].label, sTexts[i].text, FALSE);
        CheckLoseText(sTexts[i].label, sTexts[i].text, TRUE);
    }
    gBattleTypeFlags = 0;
    printf("selftest-line-break: %d checks, %d failed\n", sBreakChecks, sBreakFailures);
    return sBreakFailures ? 1 : 0;
}

// ---------------------------------------------------------------------------
// --selftest-wild-weather (EmeraldTogether expansion Phase 2): the weather table
// of the randomized wild Pokemon (src/mp_wild_random.c, PC builds), checked
// through the game's own code on real map headers:
//   1. clear weather leaves the Phase 0 weights (rarity tier 10:5:2:1 x3, time
//      of day x3 or /3, the map's area types x3, at least 1);
//   2. the owner's table, written out again here: rain Water x3; heavy rain
//      Water x3 and the rare families x2; thunder Electric x3 (Water x2); snow
//      Ice x3; sun and drought Fire x3 (Grass x2); sandstorm Ground x3 (Rock
//      x2); fog Ghost x3 (Psychic x2); every other weather changes nothing - for
//      every family, habitat and time of day. "Sun" is the drought weather:
//      WEATHER_SUNNY is Emerald's ordinary clear sky, the map weather of most
//      routes, and changes nothing (KNOWN_ISSUES G12);
//   3. underground maps ignore the weather (the same weights and the same
//      Pokemon in every weather);
//   4. the game's own roll (MPWild_RandomizeSpecies, weather read from the
//      weather engine, time of day from the clock) picks exactly the family
//      these weights pick, for land, surfing, fishing and Rock Smash;
//   5. the Battle Frontier's Pike and Pyramid keep their own Pokemon.
// --dump-wild-weights KEYS OUT writes the land weights of the maps listed in
// KEYS ("group.number" per line) for both times of day and every weather, the
// family table and the clock's time of day per hour, for the app's
// scripts/multiplayer/check_engine_spawn_weights.py (the host must match).
// ---------------------------------------------------------------------------

#include "field_weather.h"
#include "load_save.h"
#include "mp_wild_random.h"
#include "overworld.h"
#include "random.h"
#include "rtc.h"
#include "constants/layouts.h"
#include "constants/map_types.h"
#include "constants/maps.h"
#include "constants/weather.h"

extern const struct MapHeader *const *const gMapGroups[];
extern u32 MPWild_TestFamilyCount(void);
extern const struct MPWildFamily *MPWild_TestFamily(u32 index);
extern const struct MPWildMember *MPWild_TestMembers(void);
extern u32 MPWild_TestFamilyWeight(u32 index, u32 habitat, bool32 night, u8 weather);

#define NO_TYPE 0xFF

static const struct { u8 weather; u8 primary; u8 secondary; bool8 heavy; const char *name; } sOwnerWeather[] = {
    {WEATHER_RAIN,              TYPE_WATER,    NO_TYPE,      FALSE, "rain"},
    {WEATHER_DOWNPOUR,          TYPE_WATER,    NO_TYPE,      TRUE,  "heavy rain"},
    {WEATHER_RAIN_THUNDERSTORM, TYPE_ELECTRIC, TYPE_WATER,   FALSE, "thunderstorm"},
    {WEATHER_SNOW,              TYPE_ICE,      NO_TYPE,      FALSE, "snow"},
    {WEATHER_DROUGHT,           TYPE_FIRE,     TYPE_GRASS,   FALSE, "sun (drought)"},
    {WEATHER_SANDSTORM,         TYPE_GROUND,   TYPE_ROCK,    FALSE, "sandstorm"},
    {WEATHER_FOG,               TYPE_GHOST,    TYPE_PSYCHIC, FALSE, "fog"},
    {WEATHER_FOG_HORIZONTAL,    TYPE_GHOST,    TYPE_PSYCHIC, FALSE, "fog (horizontal)"},
    {WEATHER_FOG_DIAGONAL,      TYPE_GHOST,    TYPE_PSYCHIC, FALSE, "fog (diagonal)"},
};

static const u32 sHabitats[] = {MP_WILD_HABITAT_LAND, MP_WILD_HABITAT_SURF, MP_WILD_HABITAT_FISH, MP_WILD_HABITAT_ROCK};
static const char *const sHabitatNames[] = {"land", "surfing", "fishing", "Rock Smash"};

static int sWeatherChecks, sWeatherFailures;

static void ExpectWeather(const char *what, bool32 ok)
{
    sWeatherChecks++;
    if (!ok)
        sWeatherFailures++;
    printf("%s %s\n", ok ? "ok  " : "FAIL", what);
}

static void UseMap(u16 map)
{
    gMapHeader = *Overworld_GetMapHeaderByGroupAndId(MAP_GROUP(map), MAP_NUM(map));
}

static bool32 HasType(const struct MPWildFamily *family, u8 type)
{
    return type != NO_TYPE && (family->type1 == type || family->type2 == type);
}

// The weather's multiplier for a family by the owner's table (1 when neutral).
static u32 OwnerFactor(const struct MPWildFamily *family, u8 weather)
{
    u32 i, factor = 1;

    for (i = 0; i < ARRAY_COUNT(sOwnerWeather); i++)
    {
        if (sOwnerWeather[i].weather != weather)
            continue;
        if (HasType(family, sOwnerWeather[i].primary))
            factor *= 3;
        if (HasType(family, sOwnerWeather[i].secondary))
            factor *= 2;
        if (sOwnerWeather[i].heavy && family->tier >= MP_WILD_TIER_RARE)
            factor *= 2;
    }
    return factor;
}

static const char *WeatherName(u8 weather)
{
    static const char *const sOther[WEATHER_COUNT] = {
        [WEATHER_NONE] = "clear", [WEATHER_SUNNY] = "clear sky (WEATHER_SUNNY)",
        [WEATHER_SUNNY_CLOUDS] = "sunny clouds", [WEATHER_VOLCANIC_ASH] = "volcanic ash",
        [WEATHER_UNDERWATER] = "underwater", [WEATHER_SHADE] = "shade", [WEATHER_UNDERWATER_BUBBLES] = "bubbles",
        [WEATHER_ABNORMAL] = "abnormal", [WEATHER_ROUTE119_CYCLE] = "Route 119 cycle",
        [WEATHER_ROUTE123_CYCLE] = "Route 123 cycle", [WEATHER_DYNAMIC] = "dynamic",
    };
    u32 i;

    for (i = 0; i < ARRAY_COUNT(sOwnerWeather); i++)
    {
        if (sOwnerWeather[i].weather == weather)
            return sOwnerWeather[i].name;
    }
    return weather < WEATHER_COUNT && sOther[weather] ? sOther[weather] : "?";
}

// 1. Clear weather: the Phase 0 weights (area types as the map's own boost).
static void CheckClearWeights(const char *mapName, u32 areaTypes)
{
    static const u32 sTier[MP_WILD_TIER_COUNT] = {30, 15, 6, 3};
    u32 i, h, night, bad = 0, n = MPWild_TestFamilyCount();
    char what[160];

    for (h = 0; h < ARRAY_COUNT(sHabitats); h++)
    {
        for (night = 0; night < 2; night++)
        {
            for (i = 0; i < n; i++)
            {
                const struct MPWildFamily *family = MPWild_TestFamily(i);
                u32 want = 0, got = MPWild_TestFamilyWeight(i, sHabitats[h], night, WEATHER_NONE);

                if (family->habitat & sHabitats[h])
                {
                    want = sTier[family->tier];
                    if (family->time == MP_WILD_TIME_NOCTURNAL)
                        want = night ? want * 3 : want / 3;
                    else if (family->time == MP_WILD_TIME_DIURNAL)
                        want = night ? want / 3 : want * 3;
                    if (areaTypes & ((1u << family->type1) | (1u << family->type2)))
                        want *= 3;
                    if (want == 0)
                        want = 1;
                }
                if (got != want && bad++ == 0)
                    printf("  %s, %s, %s: family %u weighs %u, want %u\n", mapName, sHabitatNames[h],
                           night ? "night" : "day", i, got, want);
            }
        }
    }
    snprintf(what, sizeof(what), "%s, clear weather: the Phase 0 weights (%u families, 4 habitats, day and night)",
             mapName, n);
    ExpectWeather(what, bad == 0);
}

// 2. and 3. Every weather against clear weather, for every family, habitat and
// time of day: the owner's factor, or none at all underground.
static void CheckWeatherTable(const char *mapName, bool32 underground)
{
    u32 w, i, h, night, n = MPWild_TestFamilyCount();
    char what[200];

    for (w = 0; w < WEATHER_COUNT; w++)
    {
        u32 bad = 0, boosted = 0;

        for (h = 0; h < ARRAY_COUNT(sHabitats); h++)
        {
            for (night = 0; night < 2; night++)
            {
                for (i = 0; i < n; i++)
                {
                    const struct MPWildFamily *family = MPWild_TestFamily(i);
                    u32 clear = MPWild_TestFamilyWeight(i, sHabitats[h], night, WEATHER_NONE);
                    u32 got = MPWild_TestFamilyWeight(i, sHabitats[h], night, w);
                    u32 want = underground ? clear : clear * OwnerFactor(family, w);

                    if (got != clear)
                        boosted++;
                    if (got != want && bad++ == 0)
                        printf("  %s, %s, %s, %s: family %u weighs %u, want %u\n", mapName, WeatherName(w),
                               sHabitatNames[h], night ? "night" : "day", i, got, want);
                }
            }
        }
        if (underground)
            snprintf(what, sizeof(what), "%s (underground), %s: the clear-weather weights", mapName, WeatherName(w));
        else
            snprintf(what, sizeof(what), "%s, %s: the owner's table (%u family weights changed)", mapName,
                     WeatherName(w), boosted);
        ExpectWeather(what, bad == 0);
    }
}

static s32 FamilyOfSpecies(u16 species)
{
    const struct MPWildMember *members = MPWild_TestMembers();
    u32 i, j, n = MPWild_TestFamilyCount();

    for (i = 0; i < n; i++)
    {
        const struct MPWildFamily *family = MPWild_TestFamily(i);
        for (j = 0; j < family->memberCount; j++)
        {
            if (members[family->firstMember + j].species == species)
                return i;
        }
    }
    return -1;
}

// 4. The game's own roll against these weights: the same random state, the
// family the weights pick against the family of the Pokemon the game made.
static void CheckGameRoll(const char *mapName, u8 weather, u16 hour, enum WildPokemonArea area, u32 habitat,
                          const char *areaName, u32 draws)
{
    u32 i, k, total, roll, mismatches = 0, n = MPWild_TestFamilyCount();
    bool32 night;
    char what[200];

    SetTimeOfDay(hour);
    night = (GetTimeOfDay() == TIME_EVENING || GetTimeOfDay() == TIME_NIGHT);
    gWeatherPtr->currWeather = weather;
    for (i = 0; i < draws; i++)
    {
        rng_value_t saved = gRngValue;
        s32 want = -1, got;

        total = 0;
        for (k = 0; k < n; k++)
            total += MPWild_TestFamilyWeight(k, habitat, night, weather);
        roll = Random32() % total;
        for (k = 0; k < n; k++)
        {
            u32 weight = MPWild_TestFamilyWeight(k, habitat, night, weather);
            if (roll < weight)
            {
                want = k;
                break;
            }
            roll -= weight;
        }
        gRngValue = saved;
        got = FamilyOfSpecies(MPWild_RandomizeSpecies(SPECIES_ZIGZAGOON, 30, area));
        if (got != want && mismatches++ == 0)
            printf("  %s, %s, %s, hour %u, draw %u: the game made family %d, the weights pick %d\n", mapName,
                   WeatherName(weather), areaName, hour, i, got, want);
    }
    snprintf(what, sizeof(what), "%s, %s, %s, %s (hour %u): the game's roll follows these weights (%u draws)",
             mapName, WeatherName(weather), areaName, night ? "night" : "day", hour, draws);
    ExpectWeather(what, mismatches == 0);
}

static void RunSpecies(u16 *out, u32 count, u8 weather, u32 seed)
{
    u32 i;

    SeedRng(seed);
    gWeatherPtr->currWeather = weather;
    for (i = 0; i < count; i++)
        out[i] = MPWild_RandomizeSpecies(SPECIES_ZIGZAGOON, 30, WILD_AREA_LAND);
}

// The share of the weight (land, day) held by families of a type, per mille.
static u32 TypeShare(u8 type, u8 weather, bool32 rareTiers)
{
    u32 i, all = 0, part = 0, n = MPWild_TestFamilyCount();

    for (i = 0; i < n; i++)
    {
        const struct MPWildFamily *family = MPWild_TestFamily(i);
        u32 weight = MPWild_TestFamilyWeight(i, MP_WILD_HABITAT_LAND, FALSE, weather);
        all += weight;
        if (rareTiers ? family->tier >= MP_WILD_TIER_RARE : HasType(family, type))
            part += weight;
    }
    return all ? part * 1000 / all : 0;
}

int NativeSelfTest_WildWeather(void)
{
    static u16 sRain[400], sClear[400];
    static const struct { u16 map; const char *name; u32 areaTypes; } sRoutes[] = {
        {MAP_ROUTE101, "Route 101", 0},
        {MAP_ROUTE119, "Route 119", (1u << TYPE_GRASS) | (1u << TYPE_BUG) | (1u << TYPE_WATER)},
        {MAP_ROUTE111, "Route 111", (1u << TYPE_GROUND) | (1u << TYPE_ROCK)},
    };
    static const struct { u8 weather; u16 hour; } sRolls[] = {
        {WEATHER_NONE, 12}, {WEATHER_RAIN, 12}, {WEATHER_DOWNPOUR, 22}, {WEATHER_RAIN_THUNDERSTORM, 19},
        {WEATHER_SUNNY, 9}, {WEATHER_SANDSTORM, 15}, {WEATHER_FOG_HORIZONTAL, 2}, {WEATHER_SHADE, 12},
    };
    static const struct { enum WildPokemonArea area; u32 habitat; const char *name; } sAreas[] = {
        {WILD_AREA_LAND, MP_WILD_HABITAT_LAND, "land"},
        {WILD_AREA_WATER, MP_WILD_HABITAT_SURF, "surfing"},
        {WILD_AREA_FISHING, MP_WILD_HABITAT_FISH, "fishing"},
        {WILD_AREA_ROCKS, MP_WILD_HABITAT_ROCK, "Rock Smash"},
    };
    const u32 caveTypes = (1u << TYPE_ROCK) | (1u << TYPE_GROUND) | (1u << TYPE_DARK) | (1u << TYPE_GHOST)
                        | (1u << TYPE_POISON) | (1u << TYPE_STEEL);
    u32 i, a, differ;
    char what[160];

    SetSaveBlocksPointers(0); // the clock reads the save's time offset when not connected
    printf("wild Pokemon and the weather (Phase 2), %u families\n", MPWild_TestFamilyCount());

    for (i = 0; i < ARRAY_COUNT(sRoutes); i++)
    {
        u32 k, same = TRUE;

        UseMap(sRoutes[i].map);
        ExpectWeather("a route is not underground", gMapHeader.mapType != MAP_TYPE_UNDERGROUND);
        // The route's own everyday weather is clear weather (G12).
        for (k = 0; k < MPWild_TestFamilyCount(); k++)
            same &= MPWild_TestFamilyWeight(k, MP_WILD_HABITAT_LAND, FALSE, gMapHeader.weather)
                 == MPWild_TestFamilyWeight(k, MP_WILD_HABITAT_LAND, FALSE, WEATHER_NONE);
        snprintf(what, sizeof(what), "%s's own weather (%s) changes nothing", sRoutes[i].name, WeatherName(gMapHeader.weather));
        ExpectWeather(what, same);
        CheckClearWeights(sRoutes[i].name, sRoutes[i].areaTypes);
        CheckWeatherTable(sRoutes[i].name, FALSE);
    }
    UseMap(MAP_GRANITE_CAVE_1F);
    ExpectWeather("Granite Cave 1F is underground", gMapHeader.mapType == MAP_TYPE_UNDERGROUND);
    CheckClearWeights("Granite Cave 1F", caveTypes);
    CheckWeatherTable("Granite Cave 1F", TRUE);

    // 4. The game's roll, on a route with area types and in the cave.
    for (i = 0; i < ARRAY_COUNT(sRolls); i++)
    {
        UseMap(MAP_ROUTE119);
        SeedRng(0x5EED0000 + i);
        for (a = 0; a < ARRAY_COUNT(sAreas); a++)
            CheckGameRoll("Route 119", sRolls[i].weather, sRolls[i].hour, sAreas[a].area, sAreas[a].habitat,
                          sAreas[a].name, 300);
    }
    UseMap(MAP_GRANITE_CAVE_1F);
    SeedRng(0xCA5E);
    CheckGameRoll("Granite Cave 1F", WEATHER_RAIN, 12, WILD_AREA_LAND, MP_WILD_HABITAT_LAND, "land", 300);
    CheckGameRoll("Granite Cave 1F", WEATHER_SANDSTORM, 22, WILD_AREA_ROCKS, MP_WILD_HABITAT_ROCK, "Rock Smash", 300);

    // 3. Underground: the same Pokemon, one by one, in rain as in clear weather;
    // on a route the rain does change them (the weather engine is really read).
    SetTimeOfDay(12);
    UseMap(MAP_GRANITE_CAVE_1F);
    RunSpecies(sRain, ARRAY_COUNT(sRain), WEATHER_RAIN, 0xB0B);
    RunSpecies(sClear, ARRAY_COUNT(sClear), WEATHER_NONE, 0xB0B);
    ExpectWeather("Granite Cave 1F: the same 400 Pokemon in rain as in clear weather",
                  memcmp(sRain, sClear, sizeof(sRain)) == 0);
    UseMap(MAP_ROUTE119);
    RunSpecies(sRain, ARRAY_COUNT(sRain), WEATHER_RAIN, 0xB0B);
    RunSpecies(sClear, ARRAY_COUNT(sClear), WEATHER_NONE, 0xB0B);
    for (i = 0, differ = 0; i < ARRAY_COUNT(sRain); i++)
        differ += sRain[i] != sClear[i];
    snprintf(what, sizeof(what), "Route 119: rain changes some of 400 Pokemon (%u differ)", differ);
    ExpectWeather(what, differ > 0);

    // 5. The Battle Frontier keeps its own Pokemon in any weather.
    gMapHeader.mapLayoutId = LAYOUT_BATTLE_FRONTIER_BATTLE_PIKE_ROOM_WILD_MONS;
    gWeatherPtr->currWeather = WEATHER_RAIN;
    ExpectWeather("Battle Pike: its own Pokemon", MPWild_RandomizeSpecies(SPECIES_SEVIPER, 60, WILD_AREA_LAND) == SPECIES_SEVIPER);
    gMapHeader.mapLayoutId = LAYOUT_BATTLE_FRONTIER_BATTLE_PYRAMID_FLOOR;
    gWeatherPtr->currWeather = WEATHER_SANDSTORM;
    ExpectWeather("Battle Pyramid: its own Pokemon", MPWild_RandomizeSpecies(SPECIES_SANDSLASH, 60, WILD_AREA_LAND) == SPECIES_SANDSLASH);

    // What a player sees on Route 101 by day (land): the share of each table's
    // types, clear weather -> that weather.
    UseMap(MAP_ROUTE101);
    printf("  Route 101, land, day: share of the weight, clear -> weather\n");
    for (i = 0; i < ARRAY_COUNT(sOwnerWeather); i++)
    {
        u32 before = TypeShare(sOwnerWeather[i].primary, WEATHER_NONE, FALSE);
        u32 after = TypeShare(sOwnerWeather[i].primary, sOwnerWeather[i].weather, FALSE);
        u32 rareBefore = TypeShare(0, WEATHER_NONE, TRUE), rareAfter = TypeShare(0, sOwnerWeather[i].weather, TRUE);

        printf("    %-16s type %2u: %3u.%u%% -> %3u.%u%%", sOwnerWeather[i].name, sOwnerWeather[i].primary,
               before / 10, before % 10, after / 10, after % 10);
        if (sOwnerWeather[i].heavy)
            printf("; rare and very rare: %u.%u%% -> %u.%u%%", rareBefore / 10, rareBefore % 10, rareAfter / 10,
                   rareAfter % 10);
        printf("\n");
        if (sOwnerWeather[i].heavy)
            ExpectWeather("heavy rain: more rare families", rareAfter > rareBefore);
        snprintf(what, sizeof(what), "%s: the main type's share at least doubles", sOwnerWeather[i].name);
        ExpectWeather(what, after >= 2 * before && before > 0);
    }

    SetTimeOfDay(0);
    gWeatherPtr->currWeather = WEATHER_NONE;
    printf("selftest-wild-weather: %d checks, %d failed\n", sWeatherChecks, sWeatherFailures);
    return sWeatherFailures ? 1 : 0;
}

int NativeSelfTest_DumpWildWeights(const char *keysPath, const char *outPath)
{
    static const char *const sTimes[] = {"morning", "day", "evening", "night"};
    FILE *keys = fopen(keysPath, "r"), *out = fopen(outPath, "w");
    char line[64];
    u32 i, n = MPWild_TestFamilyCount(), maps = 0;
    u16 hour;

    if (keys == NULL || out == NULL)
    {
        fprintf(stderr, "dump-wild-weights: cannot open %s or %s\n", keysPath, outPath);
        return 2;
    }
    SetSaveBlocksPointers(0);
    fprintf(out, "format 1\nfamilies %u\n", n);
    for (i = 0; i < n; i++)
    {
        const struct MPWildFamily *f = MPWild_TestFamily(i);
        u32 j;

        fprintf(out, "family %u %u %u %u %u %u %u %u\n", i, f->firstMember, f->memberCount, f->tier, f->habitat,
                f->time, f->type1, f->type2);
        for (j = 0; j < f->memberCount; j++)
        {
            const struct MPWildMember *m = &MPWild_TestMembers()[f->firstMember + j];
            fprintf(out, "member %u %u %u %u\n", f->firstMember + j, m->species, m->minLevel, m->depth);
        }
    }
    // The clock's time of day for each hour (hour 0 cannot be forced: 0 means
    // "no override"; it lies inside the night, NIGHT_HOUR_BEGIN..END).
    fprintf(out, "hours %d %d %d %d %d %d %d %d\n", MORNING_HOUR_BEGIN, MORNING_HOUR_END, DAY_HOUR_BEGIN,
            DAY_HOUR_END, EVENING_HOUR_BEGIN, EVENING_HOUR_END, NIGHT_HOUR_BEGIN, NIGHT_HOUR_END);
    for (hour = 1; hour < 24; hour++)
    {
        SetTimeOfDay(hour);
        fprintf(out, "hour %u %s\n", hour, sTimes[GetTimeOfDay()]);
    }
    SetTimeOfDay(0);
    while (fgets(line, sizeof(line), keys))
    {
        unsigned group, number;
        u32 night, w;

        if (sscanf(line, "%u.%u", &group, &number) != 2)
            continue;
        if (group >= MAP_GROUPS_COUNT || gMapGroups[group] == NULL)
        {
            // Groups this game does not build (the Kanto groups of an Emerald build).
            fprintf(out, "nomap %u.%u\n", group, number);
            continue;
        }
        gMapHeader = *Overworld_GetMapHeaderByGroupAndId(group, number);
        fprintf(out, "map %u.%u %u %u %u\n", group, number, gMapHeader.regionMapSectionId, gMapHeader.mapType,
                gMapHeader.mapLayoutId);
        for (night = 0; night < 2; night++)
        {
            for (w = 0; w < WEATHER_COUNT; w++)
            {
                fprintf(out, "w %u.%u %u %u", group, number, night, w);
                for (i = 0; i < n; i++)
                    fprintf(out, " %u", MPWild_TestFamilyWeight(i, MP_WILD_HABITAT_LAND, night, w));
                fputc('\n', out);
            }
        }
        maps++;
    }
    fclose(keys);
    fclose(out);
    printf("dump-wild-weights: %u maps, %u families, %u weathers\n", maps, n, WEATHER_COUNT);
    return 0;
}

// ---------------------------------------------------------------------------
// --selftest-clock (EmeraldTogether expansion Phase 11): while connected the
// game's clock is the host's world clock, which runs 12x (one world day in two
// real hours); the daily reset (VAR_DAYS, DoDailyEvents) and berry growth must
// still follow the player's real clock (src/clock.c, RtcCalcRealTime), offline
// and online alike, with no reset twice and none lost across connecting,
// disconnecting and reconnecting. Driven through the game's own
// InitTimeBasedEvents/DoTimeBasedEvents and the world mailbox as the companion
// fills it; real time is moved on through the save's clock offset (as the
// game's own clock setting does). Minute checks allow the one minute the wall
// clock may turn during a step.
// ---------------------------------------------------------------------------

#include "berry.h"
#include "clock.h"
#include "dewford_trend.h"
#include "event_data.h"
#include "multiplayer_world.h"
#include "constants/berry.h"
#include "constants/flags.h"
#include "constants/vars.h"

#define CLOCK_DAILY_FLAG  FLAG_DAILY_CONTEST_LOBBY_RECEIVED_BERRY
#define CLOCK_TREE        BERRY_TREE_ROUTE_103_CHERI_1
#define CLOCK_TREE_START  10000

static int sClockChecks, sClockFailures;
static u32 sWorldGeneration;

static void ExpectClock(const char *what, bool32 ok)
{
    sClockChecks++;
    if (!ok)
        sClockFailures++;
    printf("%s %s\n", ok ? "ok  " : "FAIL", what);
}

// The player's real clock: the wall clock less the save's clock offset.
static void WallTime(struct Time *out)
{
    struct SiiRtcInfo rtc;

    RtcGetInfo(&rtc);
    RtcCalcTimeDifference(&rtc, out, &gSaveBlock2Ptr->localTimeOffset);
}

static s32 MinutesOf(const struct Time *t)
{
    return t->days * 1440 + t->hours * 60 + t->minutes;
}

// Real time passes: the offset shrinks (kept normalised, as the game keeps it).
static void PassRealTime(s32 seconds)
{
    struct Time *o = &gSaveBlock2Ptr->localTimeOffset;
    s32 total = o->days * 86400 + o->hours * 3600 + o->minutes * 60 + o->seconds - seconds;
    s32 days = total >= 0 ? total / 86400 : -((-total + 86399) / 86400);
    s32 rest = total - days * 86400;

    o->days = days;
    o->hours = rest / 3600;
    o->minutes = (rest / 60) % 60;
    o->seconds = rest % 60;
}

// The companion's world record (MP_WORLD_FLAG_CLOCK_VALID and the seconds), then
// one world tick as the game makes each frame.
static void WorldConnect(bool32 connected, u32 worldSeconds)
{
    if (connected)
    {
        sWorldGeneration += 2;
        gMultiplayerWorldMailbox.inboundGeneration = sWorldGeneration - 1;
        gMultiplayerWorldMailbox.flags = MP_WORLD_FLAG_CLOCK_VALID;
        gMultiplayerWorldMailbox.worldSeconds = worldSeconds;
        gMultiplayerWorldMailbox.inboundGeneration = sWorldGeneration;
    }
    MultiplayerWorld_Tick(FALSE, connected);
}

static u16 TreeMinutes(void)
{
    return gSaveBlock1Ptr->berryTrees[CLOCK_TREE].minutesUntilNextStage;
}

// One DoTimeBasedEvents step: the daily flag is set before it, so the step
// clears it exactly when a daily reset ran. Checks VAR_DAYS against the real
// day, the berry minutes against the real minutes passed and the reset against
// a change of real day.
static void ClockStep(const char *label, s32 realMinutes)
{
    struct Time before, after;
    u16 daysBefore = VarGet(VAR_DAYS), treeBefore = TreeMinutes();
    s32 applied;
    bool32 reset, dayChanged;
    char what[200];

    WallTime(&before);
    FlagSet(CLOCK_DAILY_FLAG);
    DoTimeBasedEvents();
    WallTime(&after);
    applied = treeBefore - TreeMinutes();
    reset = !FlagGet(CLOCK_DAILY_FLAG);
    dayChanged = VarGet(VAR_DAYS) != daysBefore;

    snprintf(what, sizeof(what), "%s: VAR_DAYS is the real day (%u)", label, VarGet(VAR_DAYS));
    ExpectClock(what, VarGet(VAR_DAYS) == before.days || VarGet(VAR_DAYS) == after.days);
    snprintf(what, sizeof(what), "%s: a daily reset exactly when the real day changed (%s)", label,
             reset ? "reset" : "no reset");
    ExpectClock(what, reset == dayChanged);
    snprintf(what, sizeof(what), "%s: the berry tree grew by the real minutes (%d, want %d)", label, applied,
             realMinutes);
    ExpectClock(what, applied >= realMinutes && applied <= realMinutes + 1);
    snprintf(what, sizeof(what), "%s: the berry clock is the real time", label);
    ExpectClock(what, MinutesOf(&gSaveBlock2Ptr->lastBerryTreeUpdate) >= MinutesOf(&before) - 1
                   && MinutesOf(&gSaveBlock2Ptr->lastBerryTreeUpdate) <= MinutesOf(&after));
}

int NativeSelfTest_Clock(void)
{
    struct Time wall;
    struct BerryTree *tree;
    u16 day0;
    u32 world = 7 * 86400 + 13 * 3600; // world day 7, 13:00
    char what[160];

    SetSaveBlocksPointers(0);
    // The steps below move the player's clock on by up to 2 + 3 hours inside one day and by whole days
    // otherwise, and each step checks "a daily reset exactly when the real day changed". Started within
    // five hours of midnight, a step crosses midnight early and the later day-count checks are off by one
    // (a test defect, KNOWN_ISSUES D2). Pin the start to noon of the player's day, whatever the wall clock.
    WallTime(&wall);
    PassRealTime(12 * 3600 - (wall.hours * 3600 + wall.minutes * 60 + wall.seconds));
    InitDewfordTrend(); // as a new game does (the daily reset divides by its limits)
    MultiplayerWorld_Init();
    gSaveBlock1Ptr->location.mapGroup = MAP_GROUP(MAP_ROUTE101); // not a Pokemon Center
    gSaveBlock1Ptr->location.mapNum = MAP_NUM(MAP_ROUTE101);
    tree = &gSaveBlock1Ptr->berryTrees[CLOCK_TREE];
    tree->berry = 1; // Cheri
    tree->stage = BERRY_STAGE_PLANTED;
    tree->minutesUntilNextStage = CLOCK_TREE_START;
    printf("real-time daily reset and berries with the world clock (Phase 11)\n");

    // Offline: the clock is set; one real day later, one daily reset.
    InitTimeBasedEvents();
    WallTime(&wall);
    day0 = VarGet(VAR_DAYS);
    snprintf(what, sizeof(what), "offline, clock set: VAR_DAYS is the real day (%u)", day0);
    ExpectClock(what, day0 == wall.days);
    ExpectClock("offline, clock set: the game's time is the real time",
                gLocalTime.days == wall.days && gLocalTime.hours == wall.hours);
    PassRealTime(86400);
    ClockStep("offline, a real day later", 1440);
    ExpectClock("offline: VAR_DAYS moved on by one", VarGet(VAR_DAYS) == day0 + 1);

    // Connected: the game's time jumps to the world's; nothing real happened.
    WorldConnect(TRUE, world);
    ExpectClock("connected: the world clock is in use", MultiplayerWorld_HasClock());
    ClockStep("connected, the world clock days ahead", 0);
    snprintf(what, sizeof(what), "connected: the game's time is the world's (day %u, %02u:00)", gLocalTime.days,
             gLocalTime.hours);
    ExpectClock(what, gLocalTime.days == 1000 + 7 && gLocalTime.hours == 13);
    ExpectClock("connected: VAR_DAYS kept (no daily reset from the world clock)", VarGet(VAR_DAYS) == day0 + 1);

    // Connected: a world day passes in two real hours.
    world += 86400;
    PassRealTime(2 * 3600);
    WorldConnect(TRUE, world);
    ClockStep("connected, a world day = two real hours", 120);
    ExpectClock("connected: the game's time moved on a world day", gLocalTime.days == 1000 + 8);

    // Connected: a real day passes (twelve world days).
    world += 12 * 86400;
    PassRealTime(86400);
    WorldConnect(TRUE, world);
    ClockStep("connected, a real day later", 1440);
    ExpectClock("connected: VAR_DAYS moved on by one real day", VarGet(VAR_DAYS) == day0 + 2);
    ClockStep("connected, the same real day again", 0);

    // Disconnected: the game's time is the real time again; no second reset.
    WorldConnect(FALSE, 0);
    ExpectClock("disconnected: the world clock is not in use", !MultiplayerWorld_HasClock());
    ClockStep("disconnected", 0);
    WallTime(&wall);
    ExpectClock("disconnected: the game's time is the real time", gLocalTime.days == wall.days);
    ExpectClock("disconnected: VAR_DAYS kept", VarGet(VAR_DAYS) == day0 + 2);

    // Reconnected to a world clock that is behind (another world, a restored
    // host): nothing goes back, nothing resets.
    WorldConnect(TRUE, 86400 + 3600);
    ClockStep("reconnected, the world clock behind", 0);
    ExpectClock("reconnected: VAR_DAYS kept", VarGet(VAR_DAYS) == day0 + 2);
    PassRealTime(3 * 3600);
    ClockStep("reconnected, three real hours later", 180);

    // A save played while connected before Phase 11 (KNOWN_ISSUES G11): VAR_DAYS
    // and the berry clock hold world days (MP_WORLD_DAY_ORIGIN and later); real
    // time is the days since the game's clock was set, here 30.
    {
        struct Time real;
        u16 treeBefore;

        WorldConnect(FALSE, 0);
        WallTime(&wall);
        PassRealTime(-(s32)(wall.days - 30) * 86400);
        WallTime(&real);
        VarSet(VAR_DAYS, MP_WORLD_DAY_ORIGIN + 7);
        gSaveBlock2Ptr->lastBerryTreeUpdate.days = MP_WORLD_DAY_ORIGIN + 7;
        gSaveBlock2Ptr->lastBerryTreeUpdate.hours = 13;
        treeBefore = TreeMinutes();
        FlagSet(CLOCK_DAILY_FLAG);
        DoTimeBasedEvents();
        snprintf(what, sizeof(what), "an older save (VAR_DAYS %u, real day %d): VAR_DAYS back on the real day (%u)",
                 MP_WORLD_DAY_ORIGIN + 7, real.days, VarGet(VAR_DAYS));
        ExpectClock(what, VarGet(VAR_DAYS) == real.days);
        ExpectClock("an older save: the berry clock back on real time",
                    gSaveBlock2Ptr->lastBerryTreeUpdate.days == real.days);
        ExpectClock("an older save: no daily reset and no berry growth for the gap",
                    FlagGet(CLOCK_DAILY_FLAG) && TreeMinutes() == treeBefore);
        PassRealTime(86400);
        ClockStep("an older save, a real day later", 1440);
        ExpectClock("an older save: VAR_DAYS moved on by one", VarGet(VAR_DAYS) == real.days + 1);
        WorldConnect(TRUE, world + 86400);
        PassRealTime(86400);
        ClockStep("an older save connected, another real day", 1440);
        ExpectClock("an older save connected: VAR_DAYS moved on by one again", VarGet(VAR_DAYS) == real.days + 2);
    }

    WorldConnect(FALSE, 0);
    snprintf(what, sizeof(what), "the tree is still growing (%u minutes to its next stage)", TreeMinutes());
    ExpectClock(what, tree->berry == 1 && tree->stage != BERRY_STAGE_NO_BERRY);
    printf("selftest-clock: %d checks, %d failed\n", sClockChecks, sClockFailures);
    return sClockFailures ? 1 : 0;
}

// ---------------------------------------------------------------------------
// --selftest-mp-objects (KNOWN_ISSUES M15): the objects the multiplayer layer
// makes at run time (shared wild Pokemon 224-235, other players 241-243, their
// followers 244-246, the World Event Pokemon 247) have no map template. A save
// must never hold them (they came back as ghosts that crashed when talked to),
// a save that already holds them must drop them on load, and an object without
// a template must give no script instead of reading through NULL.
// ---------------------------------------------------------------------------

#include "event_object_movement.h"
#include "multiplayer.h"
#include "multiplayer_spawns.h"
#include "constants/event_objects.h"

static int sObjChecks, sObjFailures;

static void ExpectObj(const char *what, bool32 ok)
{
    sObjChecks++;
    if (!ok)
        sObjFailures++;
    printf("%s %s\n", ok ? "ok  " : "FAIL", what);
}

static void PlaceObject(u32 index, u8 localId, u16 graphicsId)
{
    struct ObjectEvent *objectEvent = &gObjectEvents[index];

    memset(objectEvent, 0, sizeof(*objectEvent));
    objectEvent->active = TRUE;
    objectEvent->localId = localId;
    objectEvent->graphicsId = graphicsId;
    objectEvent->mapGroup = MAP_GROUP(MAP_ROUTE101);
    objectEvent->mapNum = MAP_NUM(MAP_ROUTE101);
    objectEvent->spriteId = MAX_SPRITES; // no sprite
}

int NativeSelfTest_MpObjects(void)
{
    static const struct { u8 localId; const char *name; } sRuntime[] = {
        {MP_SPAWN_LOCAL_ID_BASE,                          "a shared wild Pokemon (224)"},
        {MP_SPAWN_LOCAL_ID_BASE + MP_SPAWN_MAX_SLOTS - 1, "the last shared wild Pokemon (235)"},
        {MULTIPLAYER_LOCAL_ID_BASE,                       "another player (241)"},
        {MP_WORLD_LOCAL_ID_FOLLOWER_BASE,                 "another player's follower (244)"},
        {MP_WORLD_LOCAL_ID_EVENT,                         "the World Event Pokemon (247)"},
    };
    const u16 monGraphics = OBJ_EVENT_MON | SPECIES_ZIGZAGOON;
    u8 npcLocalId;
    u32 i;
    char what[160];

    SetSaveBlocksPointers(0);
    MultiplayerWorld_Init();
    UseMap(MAP_ROUTE101);
    gSaveBlock1Ptr->location.mapGroup = MAP_GROUP(MAP_ROUTE101);
    gSaveBlock1Ptr->location.mapNum = MAP_NUM(MAP_ROUTE101);
    npcLocalId = gMapHeader.events->objectEvents[0].localId;
    // The current map's templates live in the save, as the game copies them on load.
    memcpy(gSaveBlock1Ptr->objectEventTemplates, gMapHeader.events->objectEvents,
           gMapHeader.events->objectEventCount * sizeof(struct ObjectEventTemplate));
    printf("multiplayer objects in saves (M15); Route 101's first person is local id %u\n", npcLocalId);
    memset(gObjectEvents, 0, sizeof(gObjectEvents));
    for (i = 0; i < ARRAY_COUNT(sRuntime); i++)
        PlaceObject(1 + i, sRuntime[i].localId, monGraphics);
    PlaceObject(10, npcLocalId, OBJ_EVENT_GFX_BOY_1);
    PlaceObject(11, OBJ_EVENT_ID_PLAYER, OBJ_EVENT_GFX_BRENDAN_NORMAL);

    // 1. Saving: none of them in the save; the map's person and the player are.
    SaveObjectEvents();
    for (i = 0; i < ARRAY_COUNT(sRuntime); i++)
    {
        snprintf(what, sizeof(what), "save: %s is not saved", sRuntime[i].name);
        ExpectObj(what, !gSaveBlock1Ptr->objectEvents[1 + i].active);
        snprintf(what, sizeof(what), "save: %s stays on the field until its own module removes it", sRuntime[i].name);
        ExpectObj(what, gObjectEvents[1 + i].active);
    }
    ExpectObj("save: the map's own person is saved", gSaveBlock1Ptr->objectEvents[10].active
              && gSaveBlock1Ptr->objectEvents[10].localId == npcLocalId);
    ExpectObj("save: the player is saved", gSaveBlock1Ptr->objectEvents[11].active);

    // 2. Loading a save written before the fix (expansion previews 1 and 2): the
    // shared wild Pokemon in it are dropped, the rest comes back.
    for (i = 0; i < ARRAY_COUNT(sRuntime); i++)
        gSaveBlock1Ptr->objectEvents[1 + i].active = TRUE;
    memset(gObjectEvents, 0, sizeof(gObjectEvents));
    LoadObjectEvents();
    for (i = 0; i < ARRAY_COUNT(sRuntime); i++)
    {
        snprintf(what, sizeof(what), "load: %s from an older save is dropped", sRuntime[i].name);
        ExpectObj(what, !gObjectEvents[1 + i].active);
    }
    ExpectObj("load: the map's own person comes back", gObjectEvents[10].active && gObjectEvents[10].localId == npcLocalId);
    ExpectObj("load: the player comes back", gObjectEvents[11].active);

    // 3. Talking to an object without a template: no script, no NULL read.
    PlaceObject(12, MP_SPAWN_LOCAL_ID_BASE + 3, monGraphics);
    printf("  the script of an object without a template\n");
    fflush(stdout); // a crash here is the bug itself
    ExpectObj("an object without a map template has no script (no NULL read)",
              GetObjectEventScriptPointerByObjectEventId(12) == NULL);
    PlaceObject(13, npcLocalId, OBJ_EVENT_GFX_BOY_1);
    ExpectObj("a map object keeps its script", GetObjectEventScriptPointerByObjectEventId(13) != NULL);

    printf("selftest-mp-objects: %d checks, %d failed\n", sObjChecks, sObjFailures);
    return sObjFailures ? 1 : 0;
}

// ---------------------------------------------------------------------------
// --selftest-spawn-claims: the game's side of a shared wild Pokemon claim
// (src/multiplayer_spawns.c) against inbound records as the companion writes
// them, with the claim task run as the game runs it:
//   1. a Pokemon another player is battling answers "busy" (KNOWN_ISSUES M18);
//   2. after running from one, the stale "ours" in the inbound is no grant: the
//      game waits for the host to drop it, then asks again (M17);
//   3. a Pokemon caught here that the host still lists as ours is reported again,
//      never released to the others (M16);
//   4. the first action after a reset does not reuse number 1 (M19).
// ---------------------------------------------------------------------------

#include "task.h"

extern void MultiplayerSpawns_TestShowObject(u32 index, u32 spawnId);
extern void MultiplayerSpawns_TestBeginBattle(u32 spawnId, u16 species);
extern bool32 MultiplayerSpawns_TestIsDrawn(u32 spawnId);

static int sClaimChecks, sClaimFailures;
static u32 sSpawnGeneration;

static void ExpectClaim(const char *what, bool32 ok)
{
    sClaimChecks++;
    if (!ok)
        sClaimFailures++;
    printf("%s %s\n", ok ? "ok  " : "FAIL", what);
}

static struct MultiplayerSpawnSlot SpawnSlot(u32 spawnId, u8 flags)
{
    struct MultiplayerSpawnSlot slot = {0};

    slot.spawnId = spawnId;
    slot.personality = 0x12345678 + spawnId;
    slot.species = SPECIES_ZIGZAGOON;
    slot.level = 3;
    slot.flags = flags;
    slot.x = 5 + spawnId % 4;
    slot.y = 6;
    slot.facing = DIR_SOUTH;
    return slot;
}

// The companion's inbound record (odd generation while writing), then one tick
// of the module as the game makes it on the overworld (fieldReady: the field
// is free, so the module draws its Pokemon).
static void SpawnInboundTick(u32 ack, u32 count, const struct MultiplayerSpawnSlot *slots, bool32 fieldReady);
static void SpawnInbound(u32 ack, u32 count, const struct MultiplayerSpawnSlot *slots)
{
    SpawnInboundTick(ack, count, slots, FALSE);
}

static void SpawnInboundTick(u32 ack, u32 count, const struct MultiplayerSpawnSlot *slots, bool32 fieldReady)
{
    u32 i;

    sSpawnGeneration += 2;
    gMultiplayerSpawnMailbox.inboundGeneration = sSpawnGeneration - 1;
    gMultiplayerSpawnMailbox.flags = MP_SPAWN_FLAG_ENABLED;
    gMultiplayerSpawnMailbox.actionAck = ack;
    gMultiplayerSpawnMailbox.mapGroup = MAP_GROUP(MAP_ROUTE101);
    gMultiplayerSpawnMailbox.mapNum = MAP_NUM(MAP_ROUTE101);
    gMultiplayerSpawnMailbox.count = count;
    for (i = 0; i < MP_SPAWN_MAX_SLOTS; i++)
    {
        struct MultiplayerSpawnSlot slot = {0};
        if (i < count)
            slot = slots[i];
        memcpy((void *)&gMultiplayerSpawnMailbox.slots[i], &slot, sizeof(slot));
    }
    gMultiplayerSpawnMailbox.inboundGeneration = sSpawnGeneration;
    MultiplayerSpawns_Tick(fieldReady, TRUE);
}

static void ResetSpawnTest(void)
{
    SetSaveBlocksPointers(0);
    MultiplayerWorld_Init(); // and the spawn module
    UseMap(MAP_ROUTE101);
    if (gMapHeader.mapLayout == NULL)
        gMapHeader.mapLayout = GetMapLayout(gMapHeader.mapLayoutId);
    gSaveBlock1Ptr->location.mapGroup = MAP_GROUP(MAP_ROUTE101);
    gSaveBlock1Ptr->location.mapNum = MAP_NUM(MAP_ROUTE101);
    gMain.callback2 = CB2_Overworld;
    ResetTasks();
    sSpawnGeneration = 0;
}

static u32 ActionSeq(void)
{
    return gMultiplayerSpawnMailbox.local.action.seq;
}

int NativeSelfTest_SpawnClaims(void)
{
    struct MultiplayerSpawnSlot slots[2];
    u32 seq, firstSeq;
    char what[160];

    printf("shared wild Pokemon claims in the game (multiplayer_spawns.c)\n");

    // 1. Busy.
    ResetSpawnTest();
    slots[0] = SpawnSlot(101, MP_SPAWN_SLOT_BUSY);
    SpawnInbound(0, 1, slots);
    ExpectClaim("the inbound record turned shared spawns on", MultiplayerSpawns_IsActive());
    MultiplayerSpawns_TestShowObject(0, 101);
    gSpecialVar_LastTalked = MP_SPAWN_LOCAL_ID_BASE;
    ExpectClaim("talking to a shared wild Pokemon starts a claim", MultiplayerSpawns_TryClaimTalked());
    RunTasks();
    snprintf(what, sizeof(what), "one another player is battling: the busy message (VAR_RESULT %u, want 0)", gSpecialVar_Result);
    ExpectClaim(what, gSpecialVar_Result == 0);
    ExpectClaim("and no claim was sent for it", ActionSeq() == 0);

    // 2. Ran from it: the stale "ours" is no grant.
    ResetSpawnTest();
    slots[0] = SpawnSlot(102, MP_SPAWN_SLOT_MINE);
    MultiplayerSpawns_TestShowObject(1, 102);
    MultiplayerSpawns_TestBeginBattle(102, SPECIES_ZIGZAGOON); // granted, battling
    SpawnInbound(0, 1, slots);
    ExpectClaim("nothing is sent during the battle", ActionSeq() == 0);
    gBattleOutcome = B_OUTCOME_RAN;
    ExpectClaim("the battle's end is the shared Pokemon's", MultiplayerSpawns_OnScriptedBattleEnd());
    SpawnInbound(0, 1, slots); // the host has not seen the result yet: still ours
    firstSeq = seq = ActionSeq();
    ExpectClaim("the result \"ran\" is sent", gMultiplayerSpawnMailbox.local.action.kind == MP_SPAWN_ACTION_RESULT
                && gMultiplayerSpawnMailbox.local.action.result == MP_WORLD_RESULT_RAN && seq != 0);
    snprintf(what, sizeof(what), "the first action after a reset is not number 1 (it is %u; M19)", seq);
    ExpectClaim(what, seq != 1);
    gSpecialVar_LastTalked = MP_SPAWN_LOCAL_ID_BASE + 1;
    gSpecialVar_Result = 2;
    MultiplayerSpawns_TryClaimTalked();
    RunTasks();
    ExpectClaim("talked to again at once: the stale \"ours\" is no grant", gSpecialVar_Result != 1);
    ExpectClaim("and no new action while the result is unanswered", ActionSeq() == seq);
    slots[0] = SpawnSlot(102, 0);
    SpawnInbound(seq, 1, slots); // the host has the result: free again
    RunTasks();
    ExpectClaim("once the host lets it go, the game asks for it again",
                gMultiplayerSpawnMailbox.local.action.kind == MP_SPAWN_ACTION_CLAIM && ActionSeq() == seq + 1
                && gSpecialVar_Result != 1);
    seq = ActionSeq();
    slots[0] = SpawnSlot(102, MP_SPAWN_SLOT_MINE);
    SpawnInbound(seq, 1, slots); // granted
    RunTasks();
    ExpectClaim("and the host's new grant starts the battle", gSpecialVar_Result == 1);

    // 3. Caught here, the host still lists it as ours: report again, never release.
    ResetSpawnTest();
    slots[0] = SpawnSlot(103, MP_SPAWN_SLOT_MINE);
    MultiplayerSpawns_TestShowObject(2, 103);
    MultiplayerSpawns_TestBeginBattle(103, SPECIES_ZIGZAGOON);
    SpawnInbound(0, 1, slots);
    gBattleOutcome = B_OUTCOME_CAUGHT;
    MultiplayerSpawns_OnScriptedBattleEnd();
    SpawnInbound(0, 1, slots);
    seq = ActionSeq();
    ExpectClaim("the result \"caught\" is sent", gMultiplayerSpawnMailbox.local.action.kind == MP_SPAWN_ACTION_RESULT
                && gMultiplayerSpawnMailbox.local.action.result == MP_WORLD_RESULT_CAUGHT);
    snprintf(what, sizeof(what), "again not number 1 after the next reset (%u; from the frame counter, %u in the first run)",
             seq, firstSeq);
    ExpectClaim(what, seq != 1);
    SpawnInbound(seq, 1, slots); // answered, but the host still says ours
    ExpectClaim("still ours on the host: \"caught\" is sent again, never a release",
                ActionSeq() == seq + 1 && gMultiplayerSpawnMailbox.local.action.kind == MP_SPAWN_ACTION_RESULT
                && gMultiplayerSpawnMailbox.local.action.result == MP_WORLD_RESULT_CAUGHT);
    seq = ActionSeq();
    SpawnInbound(seq, 0, slots); // the host removed it
    ExpectClaim("once the host removed it, nothing more is sent", ActionSeq() == seq);

    // 5. The nearest first also when the field is full (KNOWN_ISSUES M26): a
    // Pokemon placed next to the player while the field already holds as many
    // as fit takes the place of the farthest one.
    {
        struct MultiplayerSpawnSlot room[4];
        u32 i, free;

        ResetSpawnTest();
        ResetSpriteData();
        FreeAllSpritePalettes();
        memset(gObjectEvents, 0, sizeof(gObjectEvents));
        gSaveBlock1Ptr->pos.x = 10; // the player's tile (the camera's corner with MAP_OFFSET)
        gSaveBlock1Ptr->pos.y = 10;
        // The map's people, the other players and their followers: room for
        // exactly two shared Pokemon above the module's reserve of four.
        for (i = 0; i < OBJECT_EVENTS_COUNT - 6; i++)
            PlaceObject(i, 1 + i, OBJ_EVENT_GFX_BOY_1);
        room[0] = SpawnSlot(201, 0);
        room[0].x = 16; room[0].y = 10; // 6 tiles away
        room[1] = SpawnSlot(202, 0);
        room[1].x = 16; room[1].y = 13; // 9 tiles away
        SpawnInboundTick(0, 2, room, TRUE);
        ExpectClaim("room for two: both far Pokemon are drawn",
                    MultiplayerSpawns_TestIsDrawn(201) && MultiplayerSpawns_TestIsDrawn(202));
        for (i = 0, free = 0; i < OBJECT_EVENTS_COUNT; i++)
            free += !gObjectEvents[i].active;
        snprintf(what, sizeof(what), "and the reserve is kept (%u object events free, 4 wanted)", free);
        ExpectClaim(what, free == 4);
        room[2] = SpawnSlot(203, 0);
        room[2].x = 11; room[2].y = 10; // right next to the player
        SpawnInboundTick(0, 3, room, TRUE);
        ExpectClaim("a Pokemon placed next to the player is drawn although the field was full (M26)",
                    MultiplayerSpawns_TestIsDrawn(203));
        ExpectClaim("... in place of the farthest one", !MultiplayerSpawns_TestIsDrawn(202)
                    && MultiplayerSpawns_TestIsDrawn(201));
        SpawnInboundTick(0, 3, room, TRUE);
        SpawnInboundTick(0, 3, room, TRUE);
        ExpectClaim("no swapping back on the next frames", MultiplayerSpawns_TestIsDrawn(203)
                    && MultiplayerSpawns_TestIsDrawn(201) && !MultiplayerSpawns_TestIsDrawn(202));
        for (i = 0, free = 0; i < OBJECT_EVENTS_COUNT; i++)
            free += !gObjectEvents[i].active;
        ExpectClaim("the reserve is still kept", free == 4);
        // Only a clearly farther one makes room: one tile apart, nothing moves.
        room[3] = SpawnSlot(204, 0);
        room[3].x = 15; room[3].y = 10; // 5 tiles: the farthest drawn one is 6 away
        SpawnInboundTick(0, 4, room, TRUE);
        ExpectClaim("a newcomer about as far as the drawn ones waits (no swapping on near ties)",
                    !MultiplayerSpawns_TestIsDrawn(204) && MultiplayerSpawns_TestIsDrawn(201)
                    && MultiplayerSpawns_TestIsDrawn(203));
        MultiplayerSpawns_LeaveField();
        memset(gObjectEvents, 0, sizeof(gObjectEvents));
    }

    ResetTasks();
    gMain.callback2 = NULL;
    printf("selftest-spawn-claims: %d checks, %d failed\n", sClaimChecks, sClaimFailures);
    return sClaimFailures ? 1 : 0;
}

// ---------------------------------------------------------------------------
// --selftest-coop-exp (owner decision 2026-10-13: co-op battles award
// experience, PvP never does). Drives src/multiplayer_coop.c's co-op award with
// a battle's state as each game sees it: this player's own Pokemon (battler 0
// here; the slave game's is battler 2), the teammate's party (never touched)
// and two opposing trainers. Checks who gets what, the battle's formula, once
// only, no award without a co-op battle, level-ups, moves and evolution.
// ---------------------------------------------------------------------------

#include "battle_controllers.h"
#include "multiplayer_coop.h"
#include "caps.h"
#include "item.h"
#include "constants/battle.h"

static int sCoopChecks, sCoopFailures;

static void ExpectCoop(const char *what, bool32 ok)
{
    sCoopChecks++;
    if (!ok)
        sCoopFailures++;
    printf("%s %s\n", ok ? "ok  " : "FAIL", what);
}

static void CoopMon(struct Pokemon *mon, u16 species, u8 level)
{
    CreateMonWithIVs(mon, species, level, 0x1000 + species, OTID_STRUCT_PLAYER_ID, 0);
}

static void SetCoopHp(struct Pokemon *mon, u16 hp)
{
    SetMonData(mon, MON_DATA_HP, &hp);
}

static u32 CoopEvSum(struct Pokemon *mon)
{
    return GetMonData(mon, MON_DATA_HP_EV) + GetMonData(mon, MON_DATA_ATK_EV) + GetMonData(mon, MON_DATA_DEF_EV)
         + GetMonData(mon, MON_DATA_SPEED_EV) + GetMonData(mon, MON_DATA_SPATK_EV) + GetMonData(mon, MON_DATA_SPDEF_EV);
}

// The battle's Gen 6 numbers, written out independently: a trainer battle's
// base (yield x level / 7, x1.5), all of it for a Pokemon that faced the fallen
// one, half (at least 1) for the rest, then the getter's multipliers.
static u32 ExpectedCoopReward(struct Pokemon *getter, u16 species, u8 level, bool32 faced)
{
    u32 base = gSpeciesInfo[species].expYield * level / 7 * 150 / 100;
    u32 reward = faced ? base : (base / 2 ? base / 2 : 1);

    if (IsMonPastEvolutionLevel(getter))
        reward = reward * 4915 / 4096;
    if (GetMonAffectionHearts(getter) >= AFFECTION_FOUR_HEARTS)
        reward = reward * 4915 / 4096;
    return reward;
}

// Gains of one getter over the defeated Pokemon in order (its level, and so
// its multipliers, rising as the battle's would).
struct CoopExpected { u16 species; u8 level; bool8 faced; bool8 able; };

static u32 ExpectedCoopTotal(const struct Pokemon *start, const struct CoopExpected *kos, u32 count)
{
    struct Pokemon copy = *start;
    u32 k, total = 0;

    for (k = 0; k < count; k++)
    {
        u32 reward, exp;

        if (!kos[k].able || GetMonData(&copy, MON_DATA_LEVEL) >= MAX_LEVEL)
            continue;
        reward = ExpectedCoopReward(&copy, kos[k].species, kos[k].level, kos[k].faced);
        total += reward;
        exp = GetMonData(&copy, MON_DATA_EXP) + reward;
        SetMonData(&copy, MON_DATA_EXP, &exp);
        CalculateMonStats(&copy);
    }
    return total;
}

static void CoopBattleState(void)
{
    u32 b;

    gBattlersCount = MAX_BATTLERS_COUNT;
    for (b = 0; b < MAX_BATTLERS_COUNT; b++)
        gBattlerPositions[b] = b;
    gBattlerBattleController[0] = BATTLE_CONTROLLER_PLAYER;       // this player
    gBattlerBattleController[1] = BATTLE_CONTROLLER_OPPONENT;     // trainer A
    gBattlerBattleController[2] = BATTLE_CONTROLLER_LINK_PARTNER; // the teammate
    gBattlerBattleController[3] = BATTLE_CONTROLLER_OPPONENT;     // trainer B
    memset(gBattlerPartyIndexes, 0, sizeof(gBattlerPartyIndexes));
    gAbsentBattlerFlags = 0;
}

#include "party_menu.h"

// Game text as plain ASCII for the log (letters, digits, common punctuation).
static const char *ConvertToAscii(const u8 *text)
{
    static char out[256];
    u32 n = 0;

    for (; *text != EOS && n < sizeof(out) - 1; text++)
    {
        u8 c = *text;

        if (c >= CHAR_A && c <= CHAR_Z)
            out[n++] = 'A' + (c - CHAR_A);
        else if (c >= CHAR_a && c <= CHAR_z)
            out[n++] = 'a' + (c - CHAR_a);
        else if (c >= CHAR_0 && c <= CHAR_9)
            out[n++] = '0' + (c - CHAR_0);
        else if (c == CHAR_EXTRA_SYMBOL || c == EXT_CTRL_CODE_BEGIN)
            text++; // a control code and its argument
        else
            out[n++] = c == CHAR_EXCL_MARK ? '!' : c == CHAR_QUESTION_MARK ? '?' : c == CHAR_PERIOD ? '.'
                     : c == CHAR_COMMA ? ',' : c == CHAR_HYPHEN ? '-' : ' ';
    }
    out[n] = 0;
    return out;
}

static u16 sCoopPromptMove;
static bool8 sCoopForgot;

static u32 RunCoopAward(u32 *messages, u32 *moveFull, u32 *evolveSlot, u16 *evolveTo, bool32 forgetFirst)
{
    u32 steps = 0;

    *messages = *moveFull = 0;
    *evolveSlot = PARTY_SIZE;
    *evolveTo = SPECIES_NONE;
    for (;;)
    {
        MultiplayerCoop_ExpStep();
        if (gSpecialVar_Result == MP_COOP_EXP_DONE || ++steps > 200)
            break;
        if (gSpecialVar_Result == MP_COOP_EXP_MESSAGE)
        {
            printf("     message: %s\n", ConvertToAscii(gStringVar4));
            (*messages)++;
        }
        else if (gSpecialVar_Result == MP_COOP_EXP_MOVE_FULL)
        {
            (*moveFull)++;
            if (forgetFirst && *moveFull == 1)
            {
                sCoopPromptMove = gMoveToLearn;
                sCoopForgot = MultiplayerCoop_TestForget(0);
            }
            else
                MultiplayerCoop_ExpSkipMove();
            printf("     move prompt: %s\n", ConvertToAscii(gStringVar4));
        }
        else if (gSpecialVar_Result == MP_COOP_EXP_EVOLVE)
        {
            bool32 canStop = TRUE;

            *evolveSlot = gSpecialVar_0x8005;
            *evolveTo = GetEvolutionTargetSpecies(&gParties[B_TRAINER_PLAYER][*evolveSlot], EVO_MODE_BATTLE_ONLY, 0, NULL, &canStop, CHECK_EVO);
            printf("     evolution offered: slot %u\n", *evolveSlot);
        }
    }
    return steps;
}

// Parity with the battle's own path. MultiplayerCoop_ExpReward repeats the formula of Cmd_getexp (states 1
// and 2) for a game that did not run the battle script. This writes that state machine's arithmetic out
// once more and runs the multiplier chain through the REAL ApplyExperienceMultipliers and
// GetSoftLevelCapExpValue, for getters carrying every multiplier, so a later upstream merge that changes
// the battle's experience rules fails here instead of silently drifting from co-op.
extern void ApplyExperienceMultipliers(s32 *expAmount, u8 expGetterMonId, u8 faintedBattler);

static u32 BattlePathReward(u32 slot, u16 species, u8 foeLevel, bool32 wasSentOut)
{
    struct Pokemon *getter = &gParties[B_TRAINER_PLAYER][slot];
    u32 level = GetMonData(getter, MON_DATA_LEVEL), calculated = gSpeciesInfo[species].expYield * foeLevel;
    u32 expValue, shareValue;
    s32 reward;

    calculated /= (GetConfig(B_SCALED_EXP) >= GEN_5 && GetConfig(B_SCALED_EXP) != GEN_6) ? 5 : 7;
    if (GetConfig(B_TRAINER_EXP_MULTIPLIER) <= GEN_7)
        calculated = calculated * 150 / 100; // always a trainer battle here
    expValue = calculated; // B_SPLIT_EXP >= GEN_6
    shareValue = calculated / 2 ? calculated / 2 : 1;
    reward = wasSentOut ? GetSoftLevelCapExpValue(level, expValue) : 0;
    if (reward == 0) // the permanent Exp. Share (IsGen6ExpShareEnabled)
        reward += GetSoftLevelCapExpValue(level, shareValue);
    gBattleMons[1].level = foeLevel;
    ApplyExperienceMultipliers(&reward, slot, 1);
    if (B_EXP_CAP_TYPE == EXP_CAP_HARD && reward != 0)
    {
        u32 cap = GetCurrentLevelCap(), have = GetMonData(getter, MON_DATA_EXP);
        u32 growth = gSpeciesInfo[GetMonData(getter, MON_DATA_SPECIES)].growthRate;

        if (level >= cap)
            reward = 0;
        else if (gExperienceTables[growth][cap] < have + reward)
            reward = gExperienceTables[growth][cap] - have;
    }
    return reward > 0 ? reward : 0;
}

static void CoopExpParity(void)
{
    static const struct { u16 species; u8 level; } foes[] = {
        {SPECIES_GEODUDE, 12}, {SPECIES_MAGIKARP, 5}, {SPECIES_BLISSEY, 100}, {SPECIES_RAYQUAZA, 70}, {SPECIES_NOSEPASS, 1},
    };
    static const char *const names[] = {"plain", "traded", "Lucky Egg", "past its evolution level", "four hearts", "all of them"};
    struct Pokemon *getter = &gParties[B_TRAINER_PLAYER][0];
    u32 variant, charm, foe, faced, checked = 0, bad = 0;
    char what[200];

    InitHeap(gHeap, HEAP_SIZE); // the bag allocates from the game heap
    memset(gParties, 0, sizeof(gParties));
    for (charm = 0; charm < 2; charm++)
    {
        if (charm)
            AddBagItem(ITEM_EXP_CHARM, 1);
        for (variant = 0; variant < ARRAY_COUNT(names); variant++)
        {
            u32 level = (variant == 3 || variant == 5) ? 22 : 17, friendship = (variant == 4 || variant == 5) ? 255 : 70;
            enum Item item = (variant == 2 || variant == 5) ? ITEM_LUCKY_EGG : ITEM_NONE;
            u32 otId = (variant == 1 || variant == 5) ? 0x1234567 : 0, expBefore;

            CoopMon(getter, SPECIES_TREECKO, level); // evolves at 16: past it at 22 and 17
            if (otId)
                SetMonData(getter, MON_DATA_OT_ID, &otId);
            SetMonData(getter, MON_DATA_HELD_ITEM, &item);
            SetMonData(getter, MON_DATA_FRIENDSHIP, &friendship);
            expBefore = GetMonData(getter, MON_DATA_EXP);
            for (foe = 0; foe < ARRAY_COUNT(foes); foe++)
            {
                for (faced = 0; faced < 2; faced++)
                {
                    u32 want = BattlePathReward(0, foes[foe].species, foes[foe].level, faced);
                    u32 got = MultiplayerCoop_ExpReward(getter, foes[foe].species, foes[foe].level, faced);

                    checked++;
                    if (want != got)
                    {
                        if (!bad++)
                            printf("     first mismatch: %s getter Lv. %u%s vs species %u Lv. %u %s: battle %u, co-op %u\n",
                                   names[variant], level, charm ? " (Exp. Charm)" : "", foes[foe].species,
                                   foes[foe].level, faced ? "faced" : "shared", want, got);
                    }
                }
            }
            (void)expBefore;
        }
    }
    snprintf(what, sizeof(what), "co-op rewards equal the battle's own path in %u of %u cases (%u multiplier variants x Exp. Charm x 5 foes x faced/shared)",
             checked - bad, checked, (u32)ARRAY_COUNT(names));
    ExpectCoop(what, bad == 0 && checked == ARRAY_COUNT(names) * 2 * ARRAY_COUNT(foes) * 2);
    // The comparison must be able to fail: a getter with the multipliers is rewarded more than a plain one.
    CoopMon(getter, SPECIES_TREECKO, 17);
    {
        u32 plain = MultiplayerCoop_ExpReward(getter, SPECIES_GEODUDE, 12, TRUE);
        enum Item egg = ITEM_LUCKY_EGG;

        SetMonData(getter, MON_DATA_HELD_ITEM, &egg);
        ExpectCoop("a Lucky Egg raises the co-op reward (the comparison is not vacuous)",
                   MultiplayerCoop_ExpReward(getter, SPECIES_GEODUDE, 12, TRUE) > plain && plain > 0);
    }
    RemoveBagItem(ITEM_EXP_CHARM, 1);
}

int NativeSelfTest_CoopExp(void)
{
    struct Pokemon before[PARTY_SIZE], partner;
    struct Pokemon *own = gParties[B_TRAINER_PLAYER];
    struct Pokemon *a = gParties[B_TRAINER_OPPONENT_A], *b = gParties[B_TRAINER_OPPONENT_B];
    u32 messages, moveFull, evolveSlot, steps, gained[PARTY_SIZE], evs[PARTY_SIZE], i, exp;
    u16 evolveTo;
    char what[200];

    SetSaveBlocksPointers(0);
    MultiplayerCoop_Init();
    printf("co-op experience (owner decision 2026-10-13)\n");

    // This player's party: 0 leads; 1 never sent out, one Exp. Point from Lv. 16
    // (Treecko evolves at 16); 2 sent out after the first knockout, then
    // fainted; 3 an Egg; 4 fainted before the battle; 5 Lv. 100.
    memset(gParties, 0, sizeof(gParties));
    CoopMon(&own[0], SPECIES_ZIGZAGOON, 10);
    SetMonMoveSlot(&own[0], MOVE_TACKLE, 0);   // four moves: the next one asks
    SetMonMoveSlot(&own[0], MOVE_GROWL, 1);
    SetMonMoveSlot(&own[0], MOVE_TAIL_WHIP, 2);
    SetMonMoveSlot(&own[0], MOVE_SAND_ATTACK, 3);
    CoopMon(&own[1], SPECIES_TREECKO, 15);
    exp = gExperienceTables[gSpeciesInfo[SPECIES_TREECKO].growthRate][16] - 1;
    SetMonData(&own[1], MON_DATA_EXP, &exp);
    CalculateMonStats(&own[1]);
    CoopMon(&own[2], SPECIES_WURMPLE, 5);
    CoopMon(&own[3], SPECIES_WINGULL, 5);
    exp = TRUE;
    SetMonData(&own[3], MON_DATA_IS_EGG, &exp);
    CoopMon(&own[4], SPECIES_POOCHYENA, 8);
    SetCoopHp(&own[4], 0);
    CoopMon(&own[5], SPECIES_SLAKING, 100);
    gPartiesCount[B_TRAINER_PLAYER] = PARTY_SIZE;
    CoopMon(&gParties[B_TRAINER_PARTNER][0], SPECIES_MUDKIP, 10);
    partner = gParties[B_TRAINER_PARTNER][0];
    CoopMon(&a[0], SPECIES_GEODUDE, 12);
    CoopMon(&a[1], SPECIES_NOSEPASS, 15);
    CoopMon(&b[0], SPECIES_MAKUHITA, 14);
    memcpy(before, own, sizeof(before)); // the native battle restores this copy
    for (i = 0; i < PARTY_SIZE; i++)
        evs[i] = CoopEvSum(&own[i]);
    CoopBattleState();

    // The battle, frame by frame as each game sees it.
    for (i = 0; i < 3; i++)
        MultiplayerCoop_TestTrackFrame();             // Zigzagoon vs Geodude and Makuhita
    SetCoopHp(&a[0], 0);
    MultiplayerCoop_TestTrackFrame();                 // 1: Geodude falls
    gBattlerPartyIndexes[0] = 2;                      // Wurmple comes in
    gBattlerPartyIndexes[1] = 1;                      // Nosepass comes in
    MultiplayerCoop_TestTrackFrame();
    MultiplayerCoop_TestTrackFrame();
    SetCoopHp(&own[2], 0);                            // Wurmple faints
    MultiplayerCoop_TestTrackFrame();
    gBattlerPartyIndexes[0] = 0;                      // Zigzagoon again
    MultiplayerCoop_TestTrackFrame();
    SetCoopHp(&b[0], 0);
    MultiplayerCoop_TestTrackFrame();                 // 2: Makuhita falls
    SetCoopHp(&a[1], 0);
    MultiplayerCoop_TestTrackFrame();                 // 3: Nosepass falls
    MultiplayerCoop_TestCapture(B_OUTCOME_WON);
    snprintf(what, sizeof(what), "three defeated Pokemon recorded (%u)", MultiplayerCoop_TestKoCount());
    ExpectCoop(what, MultiplayerCoop_TestKoCount() == 3);

    // The native battle restores the party exactly; the award follows.
    memcpy(own, before, sizeof(before));
    MultiplayerCoop_ExpBegin();
    ExpectCoop("there is experience to award", gSpecialVar_Result == TRUE);
    for (i = 0; i < PARTY_SIZE; i++)
        gained[i] = GetMonData(&own[i], MON_DATA_EXP) - GetMonData(&before[i], MON_DATA_EXP);
    {
        static const struct CoopExpected zig[] = {{SPECIES_GEODUDE, 12, TRUE, TRUE}, {SPECIES_MAKUHITA, 14, TRUE, TRUE}, {SPECIES_NOSEPASS, 15, TRUE, TRUE}};
        static const struct CoopExpected tree[] = {{SPECIES_GEODUDE, 12, FALSE, TRUE}, {SPECIES_MAKUHITA, 14, FALSE, TRUE}, {SPECIES_NOSEPASS, 15, FALSE, TRUE}};
        static const struct CoopExpected wurm[] = {{SPECIES_GEODUDE, 12, FALSE, TRUE}, {SPECIES_MAKUHITA, 14, TRUE, FALSE}, {SPECIES_NOSEPASS, 15, TRUE, FALSE}};
        u32 zigWant = ExpectedCoopTotal(&before[0], zig, 3);
        u32 treeWant = ExpectedCoopTotal(&before[1], tree, 3);
        u32 wurmWant = ExpectedCoopTotal(&before[2], wurm, 3);
        u32 fullGeodude = gSpeciesInfo[SPECIES_GEODUDE].expYield * 12 / 7 * 150 / 100;

        snprintf(what, sizeof(what), "the lead, which faced all three, gets the full amount for each: %u (expected %u)", gained[0], zigWant);
        ExpectCoop(what, gained[0] == zigWant && zigWant > 0);
        snprintf(what, sizeof(what), "Geodude (Lv. 12) gives the lead %u, the battle's Gen 6 trainer formula", fullGeodude);
        ExpectCoop(what, ExpectedCoopReward(&before[0], SPECIES_GEODUDE, 12, TRUE) == fullGeodude);
        snprintf(what, sizeof(what), "a Pokemon never sent out gets the Exp. Share's half of each: %u (expected %u)", gained[1], treeWant);
        ExpectCoop(what, gained[1] == treeWant && treeWant > 0);
        snprintf(what, sizeof(what), "the half is half: %u of %u for Geodude", ExpectedCoopReward(&before[1], SPECIES_GEODUDE, 12, FALSE), fullGeodude);
        ExpectCoop(what, ExpectedCoopReward(&before[1], SPECIES_GEODUDE, 12, FALSE) == fullGeodude / 2);
        snprintf(what, sizeof(what), "a Pokemon that fainted gets only what it earned while standing (the first, shared): %u (expected %u)", gained[2], wurmWant);
        ExpectCoop(what, gained[2] == wurmWant && wurmWant > 0);
    }
    ExpectCoop("an Egg gets nothing", gained[3] == 0 && GetMonData(&own[3], MON_DATA_LEVEL) == GetMonData(&before[3], MON_DATA_LEVEL));
    ExpectCoop("a Pokemon fainted before the battle gets nothing", gained[4] == 0 && CoopEvSum(&own[4]) == evs[4]);
    ExpectCoop("a Lv. 100 Pokemon gets no experience but its EVs (Gen 5+)", gained[5] == 0 && CoopEvSum(&own[5]) > evs[5]);
    ExpectCoop("the lead and the Exp. Share getter gain EVs", CoopEvSum(&own[0]) > evs[0] && CoopEvSum(&own[1]) > evs[1]);
    ExpectCoop("the teammate's Pokemon (the partner party) is untouched",
               memcmp(&gParties[B_TRAINER_PARTNER][0], &partner, sizeof(partner)) == 0);
    snprintf(what, sizeof(what), "the Exp. Share getter grew to Lv. %u (from 15) with its stats", GetMonData(&own[1], MON_DATA_LEVEL));
    ExpectCoop(what, GetMonData(&own[1], MON_DATA_LEVEL) >= 16
               && GetMonData(&own[1], MON_DATA_MAX_HP) > GetMonData(&before[1], MON_DATA_MAX_HP));
    ExpectCoop("growing a level raised friendship", GetMonData(&own[1], MON_DATA_FRIENDSHIP) > GetMonData(&before[1], MON_DATA_FRIENDSHIP));

    // The messages, the moves of the new levels and the evolution.
    steps = RunCoopAward(&messages, &moveFull, &evolveSlot, &evolveTo, TRUE);
    snprintf(what, sizeof(what), "the award ends (%u steps, %u messages, %u move prompts)", steps, messages, moveFull);
    ExpectCoop(what, steps <= 200 && messages >= 4);
    snprintf(what, sizeof(what), "the lead knows four moves: asked once to forget one for its new move %u", sCoopPromptMove);
    ExpectCoop(what, moveFull == 1 && sCoopPromptMove != MOVE_NONE);
    ExpectCoop("forgetting the first move teaches the new one in its place",
               sCoopForgot && GetMonData(&own[0], MON_DATA_MOVE1) == sCoopPromptMove && !MonKnowsMove(&own[0], MOVE_TACKLE));
    snprintf(what, sizeof(what), "Treecko (slot 1) is offered its evolution into Grovyle (slot %u, species %u)", evolveSlot, evolveTo);
    ExpectCoop(what, evolveSlot == 1 && evolveTo == SPECIES_GROVYLE);
    {
        // Every move of every level each Pokemon grew through is known now,
        // unless it was declined at a "forget a move?" prompt.
        bool32 all = TRUE;
        u32 slot, level, known = 0;

        for (slot = 0; slot < PARTY_SIZE; slot++)
        {
            const struct LevelUpMove *learnset = GetSpeciesLevelUpLearnset(GetMonData(&own[slot], MON_DATA_SPECIES));

            for (i = 0; learnset[i].move != LEVEL_UP_MOVE_END; i++)
            {
                level = learnset[i].level;
                if (level > GetMonData(&before[slot], MON_DATA_LEVEL) && level <= GetMonData(&own[slot], MON_DATA_LEVEL))
                {
                    bool32 has = MonKnowsMove(&own[slot], learnset[i].move);
                    known += has;
                    if (!has && moveFull == 0)
                        all = FALSE;
                }
            }
        }
        snprintf(what, sizeof(what), "the moves of the new levels are learned (%u known; declined ones only after a prompt)", known);
        ExpectCoop(what, all);
    }

    // Once only: the list is consumed.
    MultiplayerCoop_ExpBegin();
    ExpectCoop("a second award gives nothing (once per defeated Pokemon)", gSpecialVar_Result == FALSE);
    memcpy(before, own, sizeof(before));
    MultiplayerCoop_TestCapture(B_OUTCOME_WON); // the same battle's end seen again
    MultiplayerCoop_ExpBegin();
    ExpectCoop("ending the same battle again finds nothing new (nothing fell since)", gSpecialVar_Result == FALSE
               && memcmp(before, own, sizeof(before)) == 0);

    // A lost battle: only what fell counts.
    MultiplayerCoop_TestReset();
    CoopMon(&a[0], SPECIES_GEODUDE, 12);
    CoopMon(&a[1], SPECIES_NOSEPASS, 15);
    CoopMon(&b[0], SPECIES_MAKUHITA, 14);
    CoopBattleState();
    memcpy(before, own, sizeof(before));
    MultiplayerCoop_TestTrackFrame();
    SetCoopHp(&a[0], 0);
    MultiplayerCoop_TestTrackFrame();
    MultiplayerCoop_TestCapture(B_OUTCOME_LOST);
    snprintf(what, sizeof(what), "a lost battle counts only the Pokemon that fell (%u)", MultiplayerCoop_TestKoCount());
    ExpectCoop(what, MultiplayerCoop_TestKoCount() == 1);
    memcpy(own, before, sizeof(before));
    MultiplayerCoop_ExpBegin();
    ExpectCoop("... and awards it", gSpecialVar_Result == TRUE && GetMonData(&own[0], MON_DATA_EXP) > GetMonData(&before[0], MON_DATA_EXP));
    RunCoopAward(&messages, &moveFull, &evolveSlot, &evolveTo, FALSE);

    // No co-op battle (PvP, or no battle): the battle's end records nothing.
    MultiplayerCoop_TestReset();
    CoopMon(&a[0], SPECIES_GEODUDE, 12);
    memcpy(before, own, sizeof(before));
    MultiplayerCoop_OnNativeResult(MP_COOP_GYM_RUSTBORO, B_OUTCOME_WON);
    MultiplayerCoop_ExpBegin();
    ExpectCoop("without a co-op battle (PvP) nothing is recorded or awarded", MultiplayerCoop_TestKoCount() == 0
               && gSpecialVar_Result == FALSE && memcmp(before, own, sizeof(before)) == 0);
    MultiplayerCoop_Init();

    CoopExpParity();

    printf("selftest-coop-exp: %d checks, %d failed\n", sCoopChecks, sCoopFailures);
    return sCoopFailures ? 1 : 0;
}

/* --selftest-coop-controller: native co-op Gym controller blocks (two-player
 * launcher proof, 2026-10-13). The master core runs both AI foes (battlers 1
 * and 3); their move action carries a default Struggle target, and their
 * replacement choice must carry a real party order. */
#include "multiplayer_battle.h"
#include "multiplayer_battle_schema.h"

void MultiplayerBattle_NativeTestShape(u8 mode, u8 cores);
static int sCoopCtlChecks, sCoopCtlFailures;

static void ExpectCoopCtl(const char *what, bool32 ok)
{
    sCoopCtlChecks++;
    if (!ok) sCoopCtlFailures++;
    printf("  %s %s\n", ok ? "ok  " : "FAIL", what);
}

/* One battler's CHOOSEACTION round: the master's request, then `reply`
 * (action, choice) from `source`; returns whether the validator accepts it. */
static bool32 CoopActionReply(u8 battler, u8 source, u8 action, u16 choice)
{
    u8 request[16] = {B_COMM_TO_CONTROLLER, 0, 0, 0, 8, 0, 0, 0, CONTROLLER_CHOOSEACTION};
    u8 reply[16] = {B_COMM_TO_ENGINE, 0, 0, 0, 8, 0, 0, 0, CONTROLLER_TWORETURNVALUES};
    MultiplayerBattle_ResetControllerValidation();
    request[1] = reply[1] = battler;
    if (!MultiplayerBattle_ValidateController(request, sizeof(request), 0)) return FALSE;
    MultiplayerBattle_NoteController(request, 0);
    reply[9] = action; reply[10] = choice; reply[11] = choice >> 8;
    return MultiplayerBattle_ValidateController(reply, sizeof(reply), source);
}

static bool32 CoopChosenMon(u8 battler, const u8 *order)
{
    u8 party[20] = {B_COMM_TO_CONTROLLER, 0, 0, 0, 12, 0, 0, 0, CONTROLLER_CHOOSEPOKEMON, 0, 6, 0, 0x10, 0x32, 0x54, 0, 0};
    u8 chosen[16] = {B_COMM_TO_ENGINE, 0, 0, 0, 8, 0, 0, 0, CONTROLLER_CHOSENMONRETURNVALUE, 1};
    MultiplayerBattle_ResetControllerValidation();
    party[1] = chosen[1] = battler;
    if (!MultiplayerBattle_ValidateController(party, sizeof(party), 0)) return FALSE;
    MultiplayerBattle_NoteController(party, 0);
    memcpy(chosen + 10, order, 3);
    return MultiplayerBattle_ValidateController(chosen, sizeof(chosen), 0);
}

int NativeSelfTest_CoopController(void)
{
    static const u8 identity[3] = {0x10, 0x32, 0x54}, stale[3] = {0xF7, 0x00, 0x9C};
    printf("co-op Gym controller blocks\n");

    MultiplayerBattle_NativeTestShape(MP_BATTLE_PHASE_COOP, 2);
    ExpectCoopCtl("co-op shape: four battlers, two cores, master owns 0/1/3",
        MultiplayerBattle_IsCoop() && MultiplayerBattle_GetBattlerCount() == 4
        && MultiplayerBattle_GetBattlerOwner(1) == 0 && MultiplayerBattle_GetBattlerOwner(2) == 1
        && MultiplayerBattle_GetBattlerOwner(3) == 0);
    // The failure the launcher proof found: battler 3's AI move action with
    // its default target, the opposing player battler 2.
    ExpectCoopCtl("AI foe 3: move action with target 2 (the proof's refused block)",
        CoopActionReply(3, 0, B_ACTION_USE_MOVE, 2 << 8));
    ExpectCoopCtl("AI foe 1: move action with target 0", CoopActionReply(1, 0, B_ACTION_USE_MOVE, 0 << 8));
    ExpectCoopCtl("AI foe 1: move action with target 2", CoopActionReply(1, 0, B_ACTION_USE_MOVE, 2 << 8));
    ExpectCoopCtl("AI foe: plain actions still pass", CoopActionReply(3, 0, B_ACTION_USE_MOVE, 0)
        && CoopActionReply(3, 0, B_ACTION_SWITCH, 0) && CoopActionReply(1, 0, B_ACTION_USE_ITEM, 0));
    ExpectCoopCtl("AI foe: a target on its own side is refused",
        !CoopActionReply(3, 0, B_ACTION_USE_MOVE, 1 << 8) && !CoopActionReply(3, 0, B_ACTION_USE_MOVE, 3 << 8));
    ExpectCoopCtl("AI foe: a target past the field is refused",
        !CoopActionReply(3, 0, B_ACTION_USE_MOVE, 4 << 8) && !CoopActionReply(3, 0, B_ACTION_USE_MOVE, 6 << 8));
    ExpectCoopCtl("AI foe: low choice bits stay zero",
        !CoopActionReply(3, 0, B_ACTION_USE_MOVE, (2 << 8) | 1) && !CoopActionReply(3, 0, B_ACTION_USE_MOVE, 0x80));
    ExpectCoopCtl("AI foe: a target only with a move action",
        !CoopActionReply(3, 0, B_ACTION_SWITCH, 2 << 8) && !CoopActionReply(1, 0, B_ACTION_RUN, 0 << 8 | 0x200));
    ExpectCoopCtl("AI foe: only the master answers for it", !CoopActionReply(3, 1, B_ACTION_USE_MOVE, 2 << 8));
    ExpectCoopCtl("trainers (battlers 0 and 2) still send no target",
        CoopActionReply(0, 0, B_ACTION_USE_MOVE, 0) && CoopActionReply(2, 1, B_ACTION_USE_MOVE, 0)
        && !CoopActionReply(0, 0, B_ACTION_USE_MOVE, 1 << 8) && !CoopActionReply(2, 1, B_ACTION_USE_MOVE, 1 << 8));
    ExpectCoopCtl("AI replacement: a real party order passes", CoopChosenMon(1, identity) && CoopChosenMon(3, identity));
    ExpectCoopCtl("AI replacement: stale transfer-buffer bytes are refused (why the AI now sends its order)",
        !CoopChosenMon(3, stale));
    MultiplayerBattle_NativeTestShape(0, 0);

    // Full Multi: four human trainers, no AI; a target in an action stays refused.
    MultiplayerBattle_NativeTestShape(MP_BATTLE_PHASE_FULL_MULTI, 4);
    ExpectCoopCtl("full Multi: battler 3's own trainer sends no target",
        CoopActionReply(3, 3, B_ACTION_USE_MOVE, 0) && !CoopActionReply(3, 3, B_ACTION_USE_MOVE, 2 << 8));
    MultiplayerBattle_NativeTestShape(0, 0);
    MultiplayerBattle_ResetControllerValidation();

    printf("selftest-coop-controller: %d checks, %d failed\n", sCoopCtlChecks, sCoopCtlFailures);
    return sCoopCtlFailures ? 1 : 0;
}

// ---------------------------------------------------------------------------
// --selftest-secret-base (expansion Phase 6): the game's side of multiplayer
// Secret Bases. The host relays each player's base record; Receive/GetOwn
// (src/secret_base.c) are the only places a record crosses the save boundary.
// Checks: a new base lands in secretBases[1..]; an unchanged repeat changes
// nothing; the owner's new version replaces the old one and keeps the player's
// registry decision; the player's own base is never replaced; a withdraw record
// removes that trainer's base; malformed records are refused; a registered
// base's location is never taken; a full table keeps the older bases.
// ---------------------------------------------------------------------------

#include "multiplayer_extras.h"
#include "constants/decorations.h"

// secret_base.c keeps its registry states private: 0 unregistered, 1 registered, 2 new
#define BASE_UNREGISTERED 0
#define BASE_REGISTERED 1

static int sBaseChecks, sBaseFailures;

static void ExpectBase(const char *what, bool32 ok)
{
    sBaseChecks++;
    if (!ok)
        sBaseFailures++;
    printf("%s %s\n", ok ? "ok  " : "FAIL", what);
}

static void MakeBase(struct SecretBase *base, u8 locationId, u8 ownerSeed)
{
    u32 i;

    memset(base, 0, sizeof(*base));
    base->secretBaseId = locationId;
    base->gender = ownerSeed & 1;
    for (i = 0; i < 4; i++)
        base->trainerName[i] = CHAR_A + ownerSeed + i;
    for (i = 4; i < PLAYER_NAME_LENGTH; i++)
        base->trainerName[i] = EOS;
    for (i = 0; i < TRAINER_ID_LENGTH; i++)
        base->trainerId[i] = 0x10 * ownerSeed + i;
    base->language = GAME_LANGUAGE;
    base->decorations[0] = 1;
    base->decorationPositions[0] = 0x23;
    base->party.species[0] = SPECIES_ZIGZAGOON;
    base->party.levels[0] = 5;
}

static void ClearAllBases(void)
{
    memset(gSaveBlock1Ptr->secretBases, 0, sizeof(gSaveBlock1Ptr->secretBases));
}

int NativeSelfTest_SecretBase(void)
{
    struct SecretBase a, a2, b, own, tomb;
    u8 out[160];
    u32 i;

    SetSaveBlocksPointers(0);
    ClearAllBases();
    MakeBase(&a, 11, 1);
    ExpectBase("a new base is saved", MultiplayerSecretBase_Receive((u8 *)&a));
    ExpectBase("  in a visitor slot, not the player's own", gSaveBlock1Ptr->secretBases[0].secretBaseId == 0
               && gSaveBlock1Ptr->secretBases[1].secretBaseId == 11);
    ExpectBase("  as a new, unregistered base", gSaveBlock1Ptr->secretBases[1].registryStatus == BASE_UNREGISTERED);
    ExpectBase("an unchanged repeat changes nothing", !MultiplayerSecretBase_Receive((u8 *)&a));

    gSaveBlock1Ptr->secretBases[1].registryStatus = BASE_REGISTERED;
    a2 = a;
    a2.secretBaseId = 12;
    a2.decorations[1] = 2;
    ExpectBase("the owner's new version replaces the old", MultiplayerSecretBase_Receive((u8 *)&a2));
    ExpectBase("  there is still one base from that player", gSaveBlock1Ptr->secretBases[1].secretBaseId == 12
               && gSaveBlock1Ptr->secretBases[2].secretBaseId == 0 && gSaveBlock1Ptr->secretBases[1].decorations[1] == 2);
    ExpectBase("  and the registry decision is kept", gSaveBlock1Ptr->secretBases[1].registryStatus == BASE_REGISTERED);

    MakeBase(&own, 21, 5);
    gSaveBlock1Ptr->secretBases[0] = own;
    a2 = own;
    a2.secretBaseId = 22;
    a2.decorations[2] = 3;
    ExpectBase("the player's own base is never replaced", !MultiplayerSecretBase_Receive((u8 *)&a2)
               && gSaveBlock1Ptr->secretBases[0].secretBaseId == 21 && gSaveBlock1Ptr->secretBases[0].decorations[2] == 0);
    ExpectBase("GetOwn returns the player's base", MultiplayerSecretBase_GetOwn(out) && out[0] == 21);
    {
        struct SecretBase copy;

        memcpy(&copy, out, sizeof(copy));
        gSaveBlock1Ptr->secretBases[0].registryStatus = BASE_REGISTERED;
        gSaveBlock1Ptr->secretBases[0].numTimesEntered = 9;
        gSaveBlock1Ptr->secretBases[0].battledOwnerToday = 1;
        MultiplayerSecretBase_GetOwn(out);
        ExpectBase("  bookkeeping bits are not shared", memcmp(&copy, out, sizeof(copy)) == 0);
    }
    gSaveBlock1Ptr->secretBases[0].secretBaseId = 0;
    ExpectBase("GetOwn says so when there is none", !MultiplayerSecretBase_GetOwn(out));
    gSaveBlock1Ptr->secretBases[0] = own;

    memset(&tomb, 0, sizeof(tomb));
    memcpy(tomb.trainerName, a.trainerName, sizeof(tomb.trainerName));
    memcpy(tomb.trainerId, a.trainerId, sizeof(tomb.trainerId));
    tomb.gender = a.gender;
    ExpectBase("a withdraw record removes that trainer's base", MultiplayerSecretBase_Receive((u8 *)&tomb)
               && gSaveBlock1Ptr->secretBases[1].secretBaseId == 0);
    ExpectBase("  and repeating it is a no-op", !MultiplayerSecretBase_Receive((u8 *)&tomb));
    memcpy(tomb.trainerName, own.trainerName, sizeof(tomb.trainerName));
    memcpy(tomb.trainerId, own.trainerId, sizeof(tomb.trainerId));
    tomb.gender = own.gender;
    ExpectBase("  a withdraw naming the player is ignored", !MultiplayerSecretBase_Receive((u8 *)&tomb)
               && gSaveBlock1Ptr->secretBases[0].secretBaseId == 21);

    MakeBase(&b, 31, 2);
    b.secretBaseId = 0xFF;
    ExpectBase("a location that does not exist is refused", !MultiplayerSecretBase_Receive((u8 *)&b));
    MakeBase(&b, 35, 2);
    ExpectBase("  and a seat number that does not exist", !MultiplayerSecretBase_Receive((u8 *)&b));
    MakeBase(&b, 31, 2);
    b.trainerName[0] = EOS;
    ExpectBase("a base without an owner name is refused", !MultiplayerSecretBase_Receive((u8 *)&b));
    MakeBase(&b, 31, 2);
    b.decorations[3] = NUM_DECORATIONS + 1;
    ExpectBase("an unknown decoration is refused", !MultiplayerSecretBase_Receive((u8 *)&b));
    MakeBase(&b, 31, 2);
    b.party.species[0] = NUM_SPECIES;
    ExpectBase("an unknown species is refused", !MultiplayerSecretBase_Receive((u8 *)&b));
    MakeBase(&b, 31, 2);
    b.party.levels[1] = MAX_LEVEL + 1;
    ExpectBase("a level over the maximum is refused", !MultiplayerSecretBase_Receive((u8 *)&b));
    ExpectBase("  nothing of that was kept", gSaveBlock1Ptr->secretBases[1].secretBaseId == 0);

    // A registered base's location is never taken by another player.
    ClearAllBases();
    gSaveBlock1Ptr->secretBases[0] = own;
    MakeBase(&a, 41, 1);
    MultiplayerSecretBase_Receive((u8 *)&a);
    gSaveBlock1Ptr->secretBases[1].toRegister = TRUE;
    MakeBase(&b, 41, 2);
    ExpectBase("a registered base's location is not taken", !MultiplayerSecretBase_Receive((u8 *)&b)
               && gSaveBlock1Ptr->secretBases[1].trainerName[0] == a.trainerName[0]);
    // The owner moving onto it keeps the older record when it cannot fit.
    MakeBase(&a2, 41, 1);
    a2.decorations[5] = 4;
    ExpectBase("the owner's own update of a registered base still lands", MultiplayerSecretBase_Receive((u8 *)&a2)
               && gSaveBlock1Ptr->secretBases[1].decorations[5] == 4);

    // A full table keeps what the player has.
    ClearAllBases();
    for (i = 1; i < SECRET_BASES_COUNT; i++)
    {
        MakeBase(&a, (i - 1) * 10 + 1, i);
        MultiplayerSecretBase_Receive((u8 *)&a);
        gSaveBlock1Ptr->secretBases[i].toRegister = TRUE; // the player registered every one
    }
    MakeBase(&b, 231, 30);
    ExpectBase("a full table of registered bases refuses a newcomer", !MultiplayerSecretBase_Receive((u8 *)&b)
               && gSaveBlock1Ptr->secretBases[19].secretBaseId == 181);
    ClearAllBases();

    // The mailbox path: a base is applied only in the calm overworld outside every secret base.
    {
        struct SecretBase offered;
        u32 generation;

        UseMap(MAP_ROUTE101);
        gSaveBlock1Ptr->location.mapGroup = MAP_GROUP(MAP_ROUTE101);
        gSaveBlock1Ptr->location.mapNum = MAP_NUM(MAP_ROUTE101);
        ClearAllBases();
        MultiplayerExtras_Init();
        MakeBase(&offered, 31, 6);
        generation = 2;
        gMultiplayerExtrasMailbox.inboundGeneration = generation + 1;
        gMultiplayerExtrasMailbox.flags = MP_EXTRAS_FLAG_ENABLED;
        gMultiplayerExtrasMailbox.recordSeq = 1;
        memcpy((void *)gMultiplayerExtrasMailbox.base, &offered, sizeof(offered));
        gMultiplayerExtrasMailbox.inboundGeneration = generation + 2;

        gSaveBlock1Ptr->location.mapGroup = MAP_GROUP(MAP_SECRET_BASE_RED_CAVE1);
        gSaveBlock1Ptr->location.mapNum = MAP_NUM(MAP_SECRET_BASE_RED_CAVE1);
        MultiplayerExtras_Tick(TRUE, TRUE);
        ExpectBase("mailbox: nothing is applied inside a secret base", gSaveBlock1Ptr->secretBases[1].secretBaseId == 0);
        gSaveBlock1Ptr->location.mapGroup = MAP_GROUP(MAP_ROUTE101);
        gSaveBlock1Ptr->location.mapNum = MAP_NUM(MAP_ROUTE101);
        MultiplayerExtras_Tick(FALSE, TRUE);
        ExpectBase("mailbox: nothing is applied while a menu or script holds the field", gSaveBlock1Ptr->secretBases[1].secretBaseId == 0);
        MultiplayerExtras_Tick(TRUE, FALSE);
        ExpectBase("mailbox: nothing is applied while disconnected", gSaveBlock1Ptr->secretBases[1].secretBaseId == 0);
        MultiplayerExtras_Tick(TRUE, TRUE);
        ExpectBase("mailbox: it is applied once the field is calm (the offer waited)", gSaveBlock1Ptr->secretBases[1].secretBaseId == 31);
        gSaveBlock1Ptr->secretBases[1].secretBaseId = 0;
        MultiplayerExtras_Tick(TRUE, TRUE);
        ExpectBase("mailbox: a record number is applied only once", gSaveBlock1Ptr->secretBases[1].secretBaseId == 0);
        ClearAllBases();
    }

    printf("selftest-secret-base: %d checks, %d failed\n", sBaseChecks, sBaseFailures);
    return sBaseFailures ? 1 : 0;
}

// ---------------------------------------------------------------------------
// --selftest-ladder (expansion Phases 8 and 10): the co-op ladder battle's code (multiplayer_ladder.c) and the opposing
// parties it builds. Every trainer the host may name must give a real party; every opposing Pokemon must come out at
// exactly the chosen level with full HP and a stat line computed for it; a Gym code keeps its meaning.
// ---------------------------------------------------------------------------

#include "multiplayer_ladder.h"
#include "multiplayer_coop.h"
#include "battle_setup.h"
#include "random.h"

static int sLadderChecks, sLadderFailures;

static void ExpectLadder(const char *what, bool32 ok)
{
    sLadderChecks++;
    if (!ok)
        sLadderFailures++;
    printf("%s %s\n", ok ? "ok  " : "FAIL", what);
}

static u32 CountParty(u32 side)
{
    u32 n = 0, i;

    for (i = 0; i < PARTY_SIZE; i++)
        n += GetMonData(&gParties[side][i], MON_DATA_SPECIES) != SPECIES_NONE;
    return n;
}

static bool32 AllAtLevel(u32 side, u32 level)
{
    u32 i;

    for (i = 0; i < PARTY_SIZE; i++)
    {
        struct Pokemon *mon = &gParties[side][i];

        if (GetMonData(mon, MON_DATA_SPECIES) == SPECIES_NONE)
            continue;
        if (GetMonData(mon, MON_DATA_LEVEL) != level || GetMonData(mon, MON_DATA_HP) != GetMonData(mon, MON_DATA_MAX_HP)
         || GetMonData(mon, MON_DATA_MAX_HP) == 0)
            return FALSE;
    }
    return TRUE;
}

int NativeSelfTest_Ladder(void)
{
    u32 code, id, usable = 0, built = 0, scaledOk = 0, level;
    u16 a, b;

    SetSaveBlocksPointers(0);
    InitHeap(gHeap, HEAP_SIZE); // the trainer party generator allocates from the game heap
    code = MultiplayerLadder_Encode(TRAINER_SIDNEY, TRAINER_PHOEBE, 57, TRUE);
    ExpectLadder("a code round-trips (trainers, level, experience)", MultiplayerLadder_IsValid(code)
                 && MultiplayerLadder_TrainerA(code) == TRAINER_SIDNEY && MultiplayerLadder_TrainerB(code) == TRAINER_PHOEBE
                 && MultiplayerLadder_Level(code) == 57 && MultiplayerLadder_ExpAllowed(code));
    ExpectLadder("the experience bit is the host's choice", !MultiplayerLadder_ExpAllowed(MultiplayerLadder_Encode(TRAINER_SIDNEY, TRAINER_PHOEBE, 57, FALSE)));
    ExpectLadder("the game's coop checks accept it and name its trainers", MultiplayerCoop_IsValidGym(code)
                 && MultiplayerCoop_GetLeader(code) == TRAINER_SIDNEY && MultiplayerCoop_GetTwin(code) == TRAINER_PHOEBE);
    ExpectLadder("Gym 1..8 keep their meaning", MultiplayerCoop_IsValidGym(1) && MultiplayerCoop_IsValidGym(8)
                 && !MultiplayerCoop_IsValidGym(0) && !MultiplayerCoop_IsValidGym(9)
                 && MultiplayerCoop_GetLeader(1) == TRAINER_ROXANNE_1 && MultiplayerCoop_GetTwin(8) == TRAINER_MP_TWIN_JUAN);
    ExpectLadder("level 0 and 101 are refused", !MultiplayerLadder_IsValid(MultiplayerLadder_Encode(TRAINER_SIDNEY, TRAINER_PHOEBE, 0, FALSE))
                 && !MultiplayerLadder_IsValid(MultiplayerLadder_Encode(TRAINER_SIDNEY, TRAINER_PHOEBE, 101, FALSE)));
    ExpectLadder("the same trainer twice is refused", !MultiplayerLadder_IsValid(MultiplayerLadder_Encode(TRAINER_SIDNEY, TRAINER_SIDNEY, 50, FALSE)));
    ExpectLadder("no trainer and a trainer past the table are refused",
                 !MultiplayerLadder_IsValid(MultiplayerLadder_Encode(0, TRAINER_PHOEBE, 50, FALSE))
                 && !MultiplayerLadder_IsValid(MultiplayerLadder_Encode(900, TRAINER_PHOEBE, 50, FALSE))
                 && !MultiplayerLadder_IsValid(MultiplayerLadder_Encode(TRAINER_PHOEBE, 863, 50, FALSE)));
    ExpectLadder("reserved bits make a code invalid", !MultiplayerLadder_IsValid(code | 0x80)
                 && !MultiplayerLadder_IsValid(code | 0x100) && !MultiplayerLadder_IsValid(code | 0x200));
    ExpectLadder("a code that is no ladder is not one", !MultiplayerLadder_IsLadder(5) && !MultiplayerLadder_IsLadder(0));

    // Every trainer the host may name builds a real party, scaled exactly.
    gBattleTypeFlags = BATTLE_TYPE_TRAINER | BATTLE_TYPE_DOUBLE | BATTLE_TYPE_MULTI | BATTLE_TYPE_TWO_OPPONENTS
                     | BATTLE_TYPE_TOWER_LINK_MULTI;
    for (id = 1; id < TRAINERS_COUNT_EMERALD; id++)
    {
        a = id;
        b = id == TRAINER_SIDNEY ? TRAINER_PHOEBE : TRAINER_SIDNEY;
        code = MultiplayerLadder_Encode(a, b, 50, FALSE);
        if (!MultiplayerLadder_IsValid(code))
            continue;
        usable++;
        gRngValue.a = 0x1234 + id; gRngValue.b = 0x5678; gRngValue.c = 0x9ABC; gRngValue.ctr = 0xDEF1;
        CreateCoopTrainerParties(a, b);
        if (CountParty(B_TRAINER_OPPONENT_A) == 0 || CountParty(B_TRAINER_OPPONENT_B) == 0)
            continue;
        built++;
        MultiplayerLadder_ScaleOpponents(code);
        if (AllAtLevel(B_TRAINER_OPPONENT_A, 50) && AllAtLevel(B_TRAINER_OPPONENT_B, 50))
            scaledOk++;
    }
    printf("ladder trainers: %u usable of %u, %u build a party, %u scale exactly\n", usable, TRAINERS_COUNT_EMERALD - 1, built, scaledOk);
    ExpectLadder("most trainers are usable and every usable one builds a party", usable > 500 && built == usable);
    ExpectLadder("every built party scales to the chosen level with full HP", scaledOk == built);

    // Levels in both directions, for the trainers the Frontier uses.
    for (level = 5; level <= 100; level += 19)
    {
        gRngValue.a = 7; gRngValue.b = level; gRngValue.c = 3; gRngValue.ctr = 1;
        CreateCoopTrainerParties(TRAINER_WALLACE, TRAINER_STEVEN);
        MultiplayerLadder_ScaleOpponents(MultiplayerLadder_Encode(TRAINER_WALLACE, TRAINER_STEVEN, level, FALSE));
        ExpectLadder("Wallace and Steven scale to a chosen level", AllAtLevel(B_TRAINER_OPPONENT_A, level) && AllAtLevel(B_TRAINER_OPPONENT_B, level));
    }
    ExpectLadder("each opponent brings three (a Gym trainer's own six are cut) and the party count follows",
                 CountParty(B_TRAINER_OPPONENT_A) == 3 && CountParty(B_TRAINER_OPPONENT_B) == 3
                 && gPartiesCount[B_TRAINER_OPPONENT_A] == 3 && gPartiesCount[B_TRAINER_OPPONENT_B] == 3);

    printf("selftest-ladder: %d checks, %d failed\n", sLadderChecks, sLadderFailures);
    return sLadderFailures ? 1 : 0;
}
